
/* organizacion/app1.js */
const sb=TNT.sb; const U=TNTUI;
if(!window.TNTEditor){window.TNTEditor={render:(plain)=>U.esc(plain||''),attach:(input)=>{const api={get:()=>({text:input.value||'',html:U.esc(input.value||'')}),set:(v)=>{input.value=v||''},focus:()=>input.focus(),lock:(v)=>{input.readOnly=!!v}};input.tntEditor=api;return api;}};}

const ROLE_OPTIONS=['Pastor/a','Colaborador','Líder','Timoteo'];
const MODULES=['organizacion','campamento','efe','lista-sabados','glosario','buffet'];
const SERVICE_AREAS=['Bienvenida','Dinámica','Ofrenda','Ministración','Palabra','Multimedia','Fotografía','Video','Diseño','Recepción','Intercesión','Sonido','Limpieza','Merch','Decoración','Buffet','Organización'];
const NAV=[
  ['my','⌂','Mi TNT'],['schedule','◷','Cronograma'],['saturdays','🗓','Sábados'],['events','◇','Eventos'],
  ['tasks','✓','Mis tareas'],['team','◉','Equipo'],['templates','▦','Plantillas']
];
const STATUS_LABEL={unread:'Pendiente',preparing:'Pendiente',progress:'En curso',review:'Lista',ready:'Lista',completed:'Terminada',replacement:'Necesita reemplazo'};
const ASSIGN_LABEL={assigned:'Pendiente de confirmar',read:'Pendiente de confirmar',accepted:'Confirmado',declined:'No puede hacerlo'};
const RUN_LABEL={pending:'Pendiente',live:'En curso',done:'Terminada'};
const PRIORITY_LABEL={low:'Baja',medium:'Media',high:'Alta'};
const ITEM_TYPE_LABEL={game:'Juego',activity:'Actividad',meal:'Comida',meeting:'Reunión',other:'Otra'};
const EVENT_STATUS_LABEL={planning:'En preparación',confirmed:'Confirmado',live:'En curso',completed:'Terminado',cancelled:'Cancelado'};

const S={session:null,account:null,person:null,view:'my',cronTab:'schedule',selectedEvent:null,selectedDay:null,satMonth:new Date(new Date().getFullYear(),new Date().getMonth(),1),
  people:[],accounts:[],events:[],eventMembers:[],tasks:[],assignees:[],templates:[],templateItems:[],days:[],items:[],responsibles:[],groups:[],groupMembers:[],groupConfigs:[],notifications:[],availability:[],workload:[],moduleAccess:[],files:[],settings:[],checkins:[]};

const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gid=()=>crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2)+Date.now().toString(36);
const today=()=>TNTUI.dateKey();
const fmtDate=d=>d?new Intl.DateTimeFormat('es-AR',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')):'';
const fmtShort=d=>d?new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short'}).format(new Date(d+'T12:00:00')):'';
const fmtTime=t=>t?String(t).slice(0,5):'—';
const age=(birthday,at=new Date())=>{if(!birthday)return null;let b=new Date(birthday+'T12:00:00'),n=at.getFullYear()-b.getFullYear();let m=at.getMonth()-b.getMonth();if(m<0||(m===0&&at.getDate()<b.getDate()))n--;return n};
const toast=(m)=>{let t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),2600)};
const errMsg=e=>e?.message||String(e||'Error');
const pBy=id=>S.people.find(p=>p.id===id); const aByPid=id=>S.accounts.find(a=>a.person_id===id);
const staffPeople=()=>S.people.filter(p=>p.active!==false&&aByPid(p.id)?.enabled!==false&&aByPid(p.id)?.staff_status==='approved');
const displayName=id=>{let p=pBy(id),a=aByPid(id);return a?.nickname||p?.full_name||'Persona'};
const avatarHtml=id=>TNTUI.avatar(pBy(id)||{},aByPid(id)||{});
const currentPersonId=()=>S.person?.id||null;
const isAdmin=()=>S.account?.system_role==='admin'; const isPastor=()=>S.account?.staff_status==='approved'&&S.account?.ministry_role==='Pastor/a';
const isEventOrganizer=id=>S.eventMembers.some(m=>m.event_id===id&&m.person_id===currentPersonId()&&m.event_role==='organizer');
const eventAction=(id,action)=>isAdmin()||isEventOrganizer(id)||!!TNT.canAction?.('organizacion',action,'*');
const canEditEvent=id=>eventAction(id,'edit_event');
const canManageEvent=id=>canEditEvent(id);
const canManagePeople=id=>eventAction(id,'manage_people');
const canCreateActivity=id=>eventAction(id,'create_activity');
const canEditActivity=id=>eventAction(id,'edit_activity');
const canAssignPeople=id=>eventAction(id,'assign_people');
const canCreateEventChat=id=>eventAction(id,'create_chat');
const canManageTemplates=()=>isAdmin()||!!TNT.canAction?.('organizacion','templates','*');
const eventBy=id=>S.events.find(e=>e.id===id); const dayBy=id=>S.days.find(d=>d.id===id); const taskBy=id=>S.tasks.find(t=>t.id===id);
const eventMembers=id=>S.eventMembers.filter(m=>m.event_id===id);
const eventTasks=id=>S.tasks.filter(t=>t.event_id===id&&!t.parent_task_id).sort((a,b)=>a.sort_order-b.sort_order);
const childrenOf=id=>S.tasks.filter(t=>t.parent_task_id===id).sort((a,b)=>a.sort_order-b.sort_order);
const eventDays=id=>S.days.filter(d=>d.event_id===id).sort((a,b)=>a.sort_order-b.sort_order);
const dayItems=id=>S.items.filter(i=>i.day_id===id).sort((a,b)=>a.sort_order-b.sort_order);
const itemPeople=id=>{const item=S.items.find(i=>i.id===id);return item?.task_id?taskPeople(item.task_id):S.responsibles.filter(r=>r.item_id===id).map(r=>r.person_id);};
const taskPeople=id=>S.assignees.filter(a=>a.task_id===id&&a.assignment_status!=='declined').map(a=>a.person_id);
const myAssignment=t=>S.assignees.find(a=>a.task_id===t.id&&a.person_id===currentPersonId());
const statusChip=(s)=>`<span class="status ${esc(s)}">${esc(STATUS_LABEL[s]||s)}</span>`;
const assignChip=(s)=>['accepted','declined'].includes(s)?`<span class="status ${esc(s)}">${esc(ASSIGN_LABEL[s]||s)}</span>`:'';
const runChip=(s)=>`<span class="chip run ${esc(s)}">${esc(RUN_LABEL[s]||s)}</span>`;

function loading(){document.getElementById('app').innerHTML='<div class="skeleton"><div><div class="spinner"></div>Cargando TNT Organización…</div></div>'}
function clearOrgModal(){const m=$('#modal');if(m)m.innerHTML='';}
function modal(html,wide=false){const alreadyOpen=!!$('#modal dialog');clearOrgModal();if(!alreadyOpen&&history.state?.tntOrgView)history.pushState({...history.state,tntOrgOverlay:'modal'},'');const host=$('#modal');host.innerHTML=`<dialog class="modal" aria-label="Detalles de organización"><section class="sheet ${wide?'wide':''}">${html}</section></dialog>`;const d=host.querySelector('dialog');if(d.showModal)d.showModal();else d.setAttribute('open','');d.addEventListener('cancel',e=>{e.preventDefault();closeModal();});d.addEventListener('click',e=>{if(e.target===d)closeModal();});$$('[data-close]',host).forEach(b=>b.onclick=closeModal);}
function closeModal(){const wasOpen=!!$('#modal dialog');clearOrgModal();if(wasOpen&&history.state?.tntOrgOverlay==='modal')U.backOverlay();}
function navigateView(view){if(!view||view===S.view)return;S.view=view;if(history.state?.tntOrgView)history.pushState({...history.state,tntOrgView:view,tntOrgOverlay:null},'');render();window.scrollTo?.(0,0);}
function initOrgHistory(){history.replaceState({...history.state,tntOrgView:S.view,tntOrgOverlay:null},'',location.href);window.addEventListener('popstate',event=>{if(document.querySelector('dialog.tnt-select-dialog,dialog.tnt-overlay,dialog.org-projection'))return;if($('#modal dialog')){if(event.state?.tntOrgOverlay==='modal')return;clearOrgModal();return}const view=event.state?.tntOrgView;if(view&&view!==S.view){S.view=view;render();}});}
function sheetHead(title,sub=''){return `<div class="sheetHead"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div><button class="close" data-close>×</button></div>`}
function empty(title,text,button='',action=''){return `<div class="empty"><b>${esc(title)}</b>${text?`<div>${esc(text)}</div>`:''}${button?`<div style="margin-top:14px"><button class="btn primary" data-action="${esc(action)}">${esc(button)}</button></div>`:''}</div>`}

async function signInGoogle(){
  const {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/organizacion/'}}); if(error)toast('Google todavía no está habilitado en Supabase. Podés entrar por email mientras tanto.');
}
async function magicLink(){let email=$('#loginEmail')?.value.trim();if(!email)return toast('Escribí tu email');let {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+'/organizacion/'}});toast(error?errMsg(error):'Te enviamos un enlace de ingreso')}
function renderLogin(){location.replace('/?next='+encodeURIComponent('/organizacion/'));}

async function boot(){await TNT.ready;if(!TNT.identity||TNT.blocked)return;S.account=TNT.account;S.person=TNT.person;S.session=TNT.session;loading();await loadAll();readDeepLink();initOrgHistory();render();openDeepLink();}

async function initAuthed(){await boot();}

async function loadAll(){
 S.errors=[];const tables={people:'tnt_people',accounts:'tnt_accounts',events:'tnt_events',eventMembers:'tnt_event_members',tasks:'tnt_tasks',assignees:'tnt_task_assignees',templates:'tnt_templates',templateItems:'tnt_template_items',days:'tnt_schedule_days',items:'tnt_schedule_items',responsibles:'tnt_schedule_responsibles',groups:'tnt_groups',groupMembers:'tnt_group_members',groupConfigs:'tnt_group_configs',notifications:'tnt_notifications',availability:'tnt_availability',workload:'tnt_monthly_workload',moduleAccess:'tnt_module_access',files:'tnt_library_items',settings:'tnt_settings',checkins:'tnt_checkins'};
 await Promise.all(Object.entries(tables).map(async([key,table])=>{try{let q=sb.from(table).select('*');if(key==='notifications')q=q.order('created_at',{ascending:false}).limit(100);const r=await q;if(r.error)throw r.error;S[key]=r.data||[];}catch(e){S.errors.push(key);console.warn('Organización: '+key,e);}}));const activeEvents=new Set(S.events.map(e=>e.id));S.tasks=S.tasks.filter(t=>activeEvents.has(t.event_id));S.days=S.days.filter(d=>activeEvents.has(d.event_id));const activeDays=new Set(S.days.map(d=>d.id));S.items=S.items.filter(i=>activeDays.has(i.day_id));S.people.sort((a,b)=>a.full_name.localeCompare(b.full_name));S.events.sort((a,b)=>a.start_date.localeCompare(b.start_date));S.account=S.accounts.find(a=>a.person_id===TNT.person.id)||TNT.account;S.person=S.people.find(p=>p.id===TNT.person.id)||TNT.person;
 if(!S.selectedEvent)S.selectedEvent=S.events.find(e=>e.end_date>=today()&&e.status!=='cancelled')?.id||S.events[0]?.id||null;if(S.selectedEvent&&!S.selectedDay)S.selectedDay=eventDays(S.selectedEvent)[0]?.id||null;
}
function readDeepLink(){const q=new URLSearchParams(location.search);S.view=q.get('view')||'my';if(q.get('date'))S.calendarDate=/^\d{4}-\d{2}-\d{2}$/.test(q.get('date'))?q.get('date'):today();if(q.get('task'))S.view='activities';if(q.get('event')){S.view='events';S.selectedEvent=q.get('event');}if(q.get('person'))S.view='team';if(S.calendarDate)S.calendarMonth=S.calendarDate.slice(0,7)+'-01';}

function navButtons(mobile=false){let arr=[...NAV];if(isAdmin())arr.push(['admin','⚙','Admin']);return arr.map(([id,ico,label])=>`<button class="navBtn ${S.view===id?'on':''} ${id==='admin'?'admin':''}" data-view="${id}"><span class="ni">${ico}</span><span>${label}</span></button>`).join('')}
function shell(content,title){const nav=[['my','home','Mi TNT'],['saturdays','calendar','Sábados'],['calendar','clock','Calendario'],['activities','tasks','Actividades'],['events','camp','Eventos'],['team','people','Equipo'],['templates','book','Plantillas'],['files','file','Archivos']];return `<div class="org-shell"><header class="org-heading"><div><div class="eyebrow">EQUIPO TNT</div><h1>${S.view==='my'?'Mi organización':esc(title)}</h1><p>${S.view==='my'?'Lo que compartimos y lo que te toca.':'Planificamos juntos lo que viene.'}</p></div><div class="actions"><button class="btn" data-open-chat>${U.icon('chat')}<span>Chat</span></button><button class="btn icon-only" data-print aria-label="Imprimir o guardar PDF">${U.icon('download')}</button></div></header><nav class="org-nav" aria-label="Organización"><div class="org-nav-track">${nav.map(([k,ico,l])=>`<button class="${S.view===k?'on':''}" data-view="${k}" aria-current="${S.view===k?'page':'false'}">${U.icon(ico)}<span>${l}</span><i aria-hidden="true"></i></button>`).join('')}</div></nav>${S.errors?.length?'<div class="tnt-error" role="alert">No pudimos actualizar algunos datos. <button class="btn" data-reload>Reintentar</button></div>':''}${S.recurringError?'<div class="tnt-error" role="alert">'+esc(S.recurringError)+'</div>':''}${content}</div>`;}
function render(){const views={my:()=>[viewMy(),'Mi TNT'],calendar:()=>[viewCalendar(),'Calendario'],saturdays:()=>[viewSaturdays(),'Sábados'],activities:()=>[viewActivities(),'Actividades'],tasks:()=>[viewActivities(),'Actividades'],events:()=>[viewEvents(),'Eventos'],team:()=>[viewTeam(),'Equipo'],templates:()=>[viewTemplates(),'Plantillas'],schedule:()=>[viewSchedule(),'Cronograma y grupos'],files:()=>[viewFiles(),'Archivos'],brief:()=>[viewBrief(),'Mi resumen'],admin:()=>[viewAdmin(),'Administración']};const [html,title]=(views[S.view]||views.my)();$('#app').innerHTML=shell(html,title);bindGlobal();bindViewSpecific();bindNew();}
function bindGlobal(){
  $$('[data-view]').forEach(b=>b.onclick=()=>navigateView(b.dataset.view));
  $$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b));
  $$('[data-event-open]').forEach(b=>b.onclick=()=>eventDetailModal(b.dataset.eventOpen));
  $$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));
  $$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));
}
async function handleAction(a,b){
  if(a==='signout')return sb.auth.signOut();if(a==='profile')return profileModal(currentPersonId());if(a==='notifications')return notificationsModal();
  if(a==='new-saturday')return saturdayCreateModal();if(a==='new-event')return eventCreateModal();if(a==='new-person')return profileModal(null,true);
  if(a==='new-template')return templateModal();if(a==='general-notification')return generalNotificationModal();
  if(a==='group-config')return groupConfigModal(S.selectedDay);if(a==='event-members')return eventMembersModal(S.selectedEvent);
}


/* organizacion/app2.js */
function viewMy(){const tasks=personalTasks(),items=personalItems(),pending=tasks.filter(t=>myAssignment(t).assignment_status==='assigned'),next=S.events.filter(e=>e.end_date>=today()&&e.status!=='cancelled').slice(0,3);return `<section class="my-summary"><div><span class="eyebrow">${esc(displayName(currentPersonId()))}</span><h2>${S.errors.length?'Actualizando tu espacio':tasks.length+items.length?'Sos parte de '+(tasks.length+items.length)+' actividades.':'Tu equipo te espera.'}</h2><p>${pending.length?pending.length+' tareas necesitan tu confirmación.':'Acá vas a encontrar tus próximas responsabilidades.'}</p><button class="btn" data-view="brief">Ver mi resumen ${U.icon('arrow')}</button></div>${avatarHtml(currentPersonId())}</section><div class="sectionHead"><h2>Mis actividades</h2><button class="btn small" data-view="activities">Ver todas</button></div><div class="activities-grid">${tasks.map(t=>taskRow(t,myAssignment(t))).join('')}${items.map(i=>scheduleItemRow(eventBy(dayBy(i.day_id).event_id),i)).join('')}${!tasks.length&&!items.length?empty('Todavía no tenés actividades asignadas','Podés ver el calendario y lo que está preparando el equipo.'):''}</div><div class="sectionHead"><h2>Lo que viene</h2><button class="btn small" data-view="calendar">Calendario</button></div><div class="grid g3">${next.map(eventCard).join('')||empty('Sin eventos próximos','')}</div>`;}
function taskRow(t,a){const e=eventBy(t.event_id),mine=Boolean(myAssignment(t)&&myAssignment(t).assignment_status!=='declined'),ids=taskPeople(t.id),date=t.planned_start||t.due_at;return `<button class="activity-card ${mine?'is-mine':''}" data-task-open="${t.id}" style="--activity-color:${['var(--tnt-lime)','var(--tnt-peach)','var(--tnt-blue)'][Math.abs(t.sort_order||0)%3]}"><div class="activity-top"><span class="activity-time">${date?U.icon('clock')+' '+U.date(date,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):esc(e?fmtDate(e.start_date):'Sin fecha')}</span>${mine?'<span class="part-badge">'+U.icon('check')+' Sos parte</span>':''}</div><h3>${esc(t.title)}</h3><p>${esc(e?.name||'Organización')}</p><div class="activity-bottom">${avatars(ids)}<span class="activity-count">${ids.length} ${ids.length===1?'responsable':'responsables'}</span><span class="activity-next">${U.icon('arrow')}</span></div><div class="chips">${statusChip(t.status)}${mine&&myAssignment(t)?assignChip(myAssignment(t).assignment_status):''}</div></button>`;}
function noteRow(n){return `<div class="rowCard"><div class="ico">🔔</div><div><b>${esc(n.title)}</b><div class="meta">${esc(n.body||'')}</div><div class="tiny">${new Date(n.created_at).toLocaleString('es-AR')}</div></div>${n.href?`<button class="btn small" data-note-href="${esc(n.href)}">Abrir</button>`:''}</div>`}
function eventCard(e){const ids=eventMembers(e.id).map(m=>m.person_id),mine=ids.includes(currentPersonId()),cancelled=e.status==='cancelled';return `<article class="event-card ${cancelled?'is-cancelled':''}"><div class="event-card-date"><b>${U.date(e.start_date,{day:'numeric'})}</b><span>${U.date(e.start_date,{month:'short'})}</span></div><div class="event-card-info"><span class="tiny">${e.kind==='saturday'?'Sábado':e.kind==='camp'?'Campamento':'Evento TNT'}${cancelled?' · CANCELADO':''}</span><h3>${esc(e.name)}</h3><p>${cancelled?'Se conserva guardado · ':''}${esc(e.location||fmtDate(e.start_date))}</p>${avatars(ids,4)}</div><button class="btn icon-only" data-event-open="${e.id}" aria-label="Ver ${esc(e.name)}">${U.icon('arrow')}</button></article>`;}
function workloadFor(pid){let now=new Date(),m=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;return S.workload.find(x=>x.person_id===pid&&x.month===m)?.assignments||0}

function viewSchedule(){
  let ev=S.events.filter(e=>e.end_date>=new Date(Date.now()-86400000*30).toISOString().slice(0,10));if(!S.selectedEvent&&ev[0])S.selectedEvent=ev[0].id;let e=eventBy(S.selectedEvent);if(!e)return `<div class="page">${empty('Todavía no hay encuentros','Prepará un sábado o creá un evento para empezar.',TNT.canAction?.('organizacion','edit_event','*')?'Crear evento':'','new-event')}</div>`;
  let days=eventDays(e.id);if(!S.selectedDay||!days.some(d=>d.id===S.selectedDay))S.selectedDay=days[0]?.id||null;
  return `<div class="page"><div class="selectBar"><select id="eventSelect" class="control" aria-label="Elegir encuentro">${S.events.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${esc(x.name)} · ${fmtShort(x.start_date)}</option>`).join('')}</select><div class="actions">${canManageEvent(e.id)?'<button class="btn" data-action="event-members">Personas</button>':''}</div></div><p class="org-help">Cronograma de ${esc(e.name)}: abrí una actividad para consultar sus instrucciones y responsables. Los responsables pueden actualizar su estado desde allí.</p><div class="tabs"><button class="tab ${S.cronTab==='schedule'?'on':''}" data-cron="schedule">Cronograma</button>${e.kind==='saturday'?'':`<button class="tab ${S.cronTab==='groups'?'on':''}" data-cron="groups">Grupos por día</button>`}</div>${e.kind==='saturday'||S.cronTab==='schedule'?schedulePanel(e,days):groupsPanel(e,days)}</div>`}
function schedulePanel(e,days){return `<div class="sectionHead"><h2>${esc(e.name)}</h2>${canManageEvent(e.id)?'<button class="btn primary small" id="addDay">+ Día</button>':''}</div>${days.length?`<div class="tabs">${days.map(d=>`<button class="tab ${d.id===S.selectedDay?'on':''}" data-day="${d.id}">${esc(d.label)}${d.date?' · '+fmtShort(d.date):''}</button>`).join('')}</div>${scheduleDayPanel(e,dayBy(S.selectedDay))}`:empty('Sin días cargados','Agregá “Día 1 / Viernes”, “Día 2 / Sábado”, etc.',canManageEvent(e.id)?'Agregar primer día':'','')}`}
function scheduleDayPanel(e,d){if(!d)return'';let its=dayItems(d.id);return `<div class="sectionHead"><h2>${esc(d.label)}</h2>${canManageEvent(e.id)?'<button class="btn primary small" id="addScheduleItem">+ Actividad</button>':''}</div>${its.length?`<div class="timeline">${its.map(i=>scheduleItemRow(e,i)).join('')}</div>`:empty('Sin actividades','Cargá juegos, comidas, reuniones y todo el cronograma.')}`}
function scheduleItemRow(e,i){const ids=itemPeople(i.id),mine=ids.includes(currentPersonId()),day=dayBy(i.day_id);return `<article class="agenda-card ${mine?'is-mine':''}"><div class="agenda-time">${esc(fmtTime(i.starts_at))}<small>${i.duration_minutes?i.duration_minutes+' min':''}</small></div><div class="agenda-main"><div class="agenda-title"><h3>${esc(i.title)}</h3>${mine?'<span class="part-badge">Sos parte</span>':''}</div><p>${esc(i.location||i.description||({game:'Juego',activity:'Actividad',meal:'Merienda / comida',meeting:'Reunión'}[i.item_type]||'Actividad'))}</p><div class="activity-bottom">${avatars(ids)}<span class="tiny">${ids.length} ${ids.length===1?'responsable':'responsables'}</span></div></div><button class="btn icon-only" data-item-open="${i.id}" aria-label="Ver ${esc(i.title)}">${U.icon('arrow')}</button></article>`;}

function groupsPanel(e,days){if(!days.length)return empty('Primero cargá los días','Los equipos se generan por día.');let d=dayBy(S.selectedDay)||days[0];let gs=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id).sort((a,b)=>a.sort_order-b.sort_order);let members=eventMembers(e.id).filter(m=>m.include_in_groups!==false);let missing=[];let cfg=S.groupConfigs.find(c=>c.event_id===e.id&&c.day_id===d.id);for(let m of members){let p=pBy(m.person_id);if(!p)continue;if((cfg?.balance_sex??true)&&(!p.sex||p.sex==='U'))missing.push(displayName(p.id)+' · sexo');if((cfg?.balance_age??true)&&!p.birthday)missing.push(displayName(p.id)+' · nacimiento')}
  return `<div class="tabs">${days.map(x=>`<button class="tab ${x.id===d.id?'on':''}" data-day="${x.id}">${esc(x.label)}</button>`).join('')}</div><div class="sectionHead"><div><h2>División · ${esc(d.label)}</h2><div class="tiny">${members.length} personas incluidas</div></div>${canManageEvent(e.id)?'<div class="actions"><button class="btn" data-action="event-members">Participantes</button><button class="btn primary" data-action="group-config">Generar / configurar</button></div>':''}</div>${missing.length?`<div class="warning">Para equilibrar correctamente faltan datos confirmados: ${esc([...new Set(missing)].join(', '))}. La app no infiere sexo por el nombre.</div>`:''}${gs.length?`<div class="groupGrid" style="margin-top:13px">${gs.map(g=>groupBox(g,gs)).join('')}</div>`:empty('Todavía no hay equipos','Configurá Rojo/Azul (o los nombres que quieras) y generá la división.')}`}
function groupBox(g,allGroups){let ms=S.groupMembers.filter(m=>m.group_id===g.id);let avg=ms.length?Math.round(ms.reduce((s,m)=>s+(m.age_snapshot||0),0)/ms.length):0;let sex=ms.reduce((o,m)=>(o[m.sex_snapshot||'U']=(o[m.sex_snapshot||'U']||0)+1,o),{});return `<section class="teamBox"><header class="teamHead"><h3><span class="teamDot" style="background:${esc(g.color)}"></span>${esc(g.name)}</h3><span class="tiny">${ms.length} · edad prom. ${avg||'—'} · F ${sex.F||0} / M ${sex.M||0}</span></header><div class="teamMembers">${ms.map(m=>{let p=pBy(m.person_id);return `<div class="member">${avatarHtml(m.person_id)}<div><b>${esc(displayName(m.person_id))}</b><div class="tiny">${m.age_snapshot??'—'} años · ${m.sex_snapshot==='F'?'F':m.sex_snapshot==='M'?'M':'Sin confirmar'}</div></div>${canManageEvent(g.event_id)?`<select data-move-person="${m.person_id}" data-from-group="${g.id}">${allGroups.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}</div>`}).join('')||'<div class="tiny">Sin personas</div>'}</div></section>`}

function viewSaturdays(){return `<div class="page"><div class="sectionHead"><div><h2>Sábados</h2><p>Prepará cada sábado cuando corresponda. Después agregá tareas y responsables.</p></div>${TNT.canAction?.('organizacion','create_saturday','*')?'<button class="btn primary" data-action="new-saturday">+ Sábado</button>':''}</div><div class="grid g2">${S.events.filter(e=>e.kind==='saturday'&&e.end_date>=today()).map(eventCard).join('')||empty('Todavía no hay sábados preparados','Creá el próximo sábado y después armá sus tareas.')}</div></div>`;}
function viewEvents(){const es=S.events.filter(e=>e.kind!=='saturday'&&(S.showPast||e.end_date>=today()));return `<div class="sectionHead"><h2>${S.showPast?'Todos los eventos':'Próximos eventos'}</h2><div class="actions"><button class="btn" data-past>${S.showPast?'Ver próximos':'Ver anteriores'}</button>${TNT.canAction?.('organizacion','edit_event','*')?'<button class="btn primary" data-action="new-event">'+U.icon('plus')+' Evento</button>':''}</div></div><div class="grid g2">${es.map(eventCard).join('')||empty('No hay eventos próximos','Elegí una fecha en el calendario para empezar.')}</div>`;}
function viewMyTasks(){return viewActivities();}
function viewTeam(){let q=(window._teamSearch||'').toLowerCase();let ps=staffPeople().filter(p=>displayName(p.id).toLowerCase().includes(q));return `<div class="page"><div class="sectionHead"><div><h2>Equipo TNT</h2><div class="tiny">${ps.length} personas del staff aprobado</div></div><div class="actions"><input class="control" id="teamSearch" placeholder="Buscar" value="${esc(window._teamSearch||'')}">${isAdmin()?'<button class="btn primary" data-action="new-person">+ Incorporar al staff</button>':''}</div></div><div class="peopleGrid">${ps.map(personCard).join('')}</div></div>`}
function personCard(p){const a=aByPid(p.id),tasks=S.assignees.filter(x=>x.person_id===p.id&&S.tasks.some(t=>t.id===x.task_id&&!U.completed(t))).length,av=S.availability.find(x=>x.person_id===p.id&&x.date===today());return `<article class="person-card"><div class="person-card-top">${U.avatar(p,a||{},'large')}<span class="tnt-pill">${av?.status==='unavailable'?'No disponible hoy':av?.status==='available'?'Disponible hoy':'Equipo TNT'}</span></div><h3>${esc(displayName(p.id))}</h3><p>${esc(a?.ministry_role||'Participante')}</p><div class="person-areas">${(a?.service_areas||[]).slice(0,3).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="person-foot"><span>${tasks} tareas activas</span><button class="btn" data-person-open="${p.id}">Ver perfil ${U.icon('arrow')}</button></div></article>`;}
function viewTemplates(){return `<div class="page"><section class="hero"><div class="eyebrow">Reutilizable</div><h1>Plantillas</h1><p>Creá tipos de actividades y sugerencias editables. Ninguna plantilla agrega tareas por sí sola.</p></section><div class="sectionHead"><h2>Plantillas</h2>${canManageTemplates()?'<button class="btn primary" data-action="new-template">+ Plantilla</button>':''}</div><div class="grid g2">${S.templates.map(t=>templateCard(t)).join('')}</div></div>`}
function templateCard(t){let items=S.templateItems.filter(i=>i.template_id===t.id).sort((a,b)=>a.sort_order-b.sort_order);return `<article class="card"><div class="quick"><div class="ico">${t.kind==='saturday'?'🗓':'▦'}</div><div class="grow"><h3>${esc(t.name)}</h3><p>${esc(t.description||'')}</p></div></div><div class="chips">${items.map(i=>`<span class="chip">${esc(i.icon||'✓')} ${esc(i.title)}</span>`).join('')}</div>${canManageTemplates()?`<div class="actions" style="margin-top:13px"><button class="btn small" data-template-edit="${t.id}">Editar</button><button class="btn small primary" data-template-start="${t.id}">Usar</button></div>`:''}</article>`}
function viewAdmin(){if(!isAdmin())return `<div class="page">${empty('Solo Admin','No tenés permiso para esta sección.')}</div>`;let accounts=S.accounts.map(a=>({a,p:pBy(a.person_id)})).filter(x=>x.p);return `<div class="page"><section class="hero"><div class="eyebrow">Sistema</div><h1>Administración</h1><p>Gestioná roles TNT, administradores, acceso a módulos y cuentas habilitadas.</p></section><div class="sectionHead"><h2>Usuarios</h2><div class="actions"><button class="btn" data-action="general-notification">Notificación general</button><button class="btn primary" data-action="new-person">+ Perfil / invitación</button></div></div><div class="list">${accounts.map(({a,p})=>adminUserRow(a,p)).join('')}</div></div>`}
function adminUserRow(a,p){return `<div class="rowCard">${avatarHtml(p.id)}<div><b>${esc(a.nickname||p.full_name)}</b><div class="meta">${esc(a.email||'Sin email')} · ${a.auth_user_id?'Cuenta vinculada':'Pendiente de ingreso'}</div><div class="chips"><span class="chip">${esc(a.ministry_role)}</span>${a.system_role==='admin'?'<span class="chip">Admin</span>':''}${!a.enabled?'<span class="status declined">Deshabilitado</span>':''}</div></div><div class="actions"><button class="btn small" data-admin-user="${p.id}">Gestionar</button></div></div>`}


/* organizacion/org3a.js */
function bindViewSpecific(){
  if(S.view==='schedule')bindSchedule();if(S.view==='saturdays')bindSaturdays();if(S.view==='team'){let x=$('#teamSearch');if(x)x.oninput=e=>{window._teamSearch=e.target.value;render()}}if(S.view==='templates'){$$('[data-template-edit]').forEach(b=>b.onclick=()=>templateModal(b.dataset.templateEdit));$$('[data-template-start]').forEach(b=>b.onclick=()=>{const t=S.templates.find(x=>x.id===b.dataset.templateStart);if(t?.kind==='saturday')saturdayCreateModal();else eventCreateModal(b.dataset.templateStart)})}if(S.view==='admin')$$('[data-admin-user]').forEach(b=>b.onclick=()=>adminUserModal(b.dataset.adminUser));
  $$('[data-note-href]').forEach(b=>b.onclick=()=>openInternal(b.dataset.noteHref));
}


function bindSchedule(){
  $('#eventSelect')?.addEventListener('change',e=>{S.selectedEvent=e.target.value;S.selectedDay=eventDays(S.selectedEvent)[0]?.id||null;render()});
  $$('[data-cron]').forEach(b=>b.onclick=()=>{S.cronTab=b.dataset.cron;render()});$$('[data-day]').forEach(b=>b.onclick=()=>{S.selectedDay=b.dataset.day;render()});
  $('#addDay')?.addEventListener('click',()=>dayModal());$('#addScheduleItem')?.addEventListener('click',()=>scheduleItemModal());
  $$('[data-item-open]').forEach(b=>b.onclick=()=>scheduleItemDetailModal(b.dataset.itemOpen));
  $$('[data-run-next]').forEach(b=>b.onclick=()=>cycleRunStatus(b.dataset.runNext));
  $$('[data-move-person]').forEach(s=>s.onchange=()=>moveGroupMember(s.dataset.movePerson,s.dataset.fromGroup,s.value));
}
function bindSaturdays(){
  $('#satPrev')?.addEventListener('click',()=>{S.satMonth=new Date(S.satMonth.getFullYear(),S.satMonth.getMonth()-1,1);render()});$('#satNext')?.addEventListener('click',()=>{S.satMonth=new Date(S.satMonth.getFullYear(),S.satMonth.getMonth()+1,1);render()});
  $$('[data-create-sat]').forEach(b=>b.onclick=()=>createSaturday(b.dataset.createSat));
}

async function createSaturday(date){let {data,error}=await sb.rpc('tnt_create_saturday',{p_date:date,p_name:'Sábado TNT'});if(error)return toast(errMsg(error));await loadAll();toast('Sábado preparado');eventDetailModal(data)}
function saturdayCreateModal(){modal(`${sheetHead('Preparar sábado','Sin tareas predefinidas: las agregás y asignás después.')}<form class="form" id="satForm"><div class="field"><label>Fecha</label><input type="date" name="date" min="${today()}" value="${esc(S.calendarDate&&S.calendarDate>=today()?S.calendarDate:'')}" required></div><div class="field"><label>Nombre</label><input name="name" value="Sábado TNT"></div><p>Primero se crea el sábado vacío. Después elegís sugerencias o redactás las tareas, y asignás responsables.</p><button class="btn primary">Crear sábado sin tareas</button></form>`);$('#satForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),{data,error}=await sb.rpc('tnt_create_saturday',{p_date:f.get('date'),p_name:f.get('name')});if(error)return toast(errMsg(error));closeModal();await loadAll();toast('Sábado creado');eventDetailModal(data)}}
function eventCreateModal(templateId=''){
 const templates=S.templates.filter(t=>t.kind!=='saturday');const chosen=templates.find(t=>t.id===templateId);
 modal(`${sheetHead('Crear evento','Definí el encuentro. Su programa comienza vacío.') }<form class="form" id="eventForm"><div class="field"><label>Tipo de actividad</label><select name="template"><option value="">Evento sin plantilla</option>${templates.map(t=>`<option value="${t.id}" ${chosen?.id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><small>La plantilla indica el tipo; sus sugerencias no se crean automáticamente.</small></div><div class="field"><label>Nombre</label><input name="name" required placeholder="Congreso TNT"></div><div class="formRow"><div class="field"><label>Desde</label><input type="date" name="start" value="${esc(S.calendarDate||'')}" required></div><div class="field"><label>Hasta</label><input type="date" name="end"></div></div><div class="field"><label>Lugar</label><input name="location"></div><div id="event-preview" class="card" aria-live="polite"></div><button class="btn primary">Crear evento vacío</button></form>`);
 const form=$('#eventForm'),preview=$('#event-preview');function draw(){const tpl=templates.find(t=>t.id===form.elements.template.value);preview.innerHTML=`<h3>Antes de crear</h3><p>${esc(tpl?.name||'Evento')} · ${esc(form.elements.name.value||'Sin nombre todavía')}</p><small>0 tareas creadas. Agregá el programa, áreas y responsables después.</small>`;}form.elements.template.onchange=draw;form.elements.name.oninput=draw;draw();
 form.onsubmit=async ev=>{ev.preventDefault();const f=new FormData(form),tpl=templates.find(t=>t.id===f.get('template'));const start=String(f.get('start')),end=String(f.get('end')||start);if(end<start)return toast('La fecha de cierre no puede ser anterior al inicio.');const payload={name:String(f.get('name')).trim(),kind:tpl?.kind||'event',activity_type_id:tpl?.id||null,start_date:start,end_date:end,location:f.get('location')||null,created_by:currentPersonId(),status:'planning'};const {data,error}=await sb.from('tnt_events').insert(payload).select('id').single();if(error)return toast(errMsg(error));const member=await sb.from('tnt_event_members').insert({event_id:data.id,person_id:currentPersonId(),event_role:'organizer'});if(member.error){await sb.from('tnt_events').delete().eq('id',data.id);return toast(errMsg(member.error));}closeModal();await loadAll();toast('Evento creado sin tareas');eventDetailModal(data.id)};
}

function eventDetailModal(id){
 let e=eventBy(id);if(!e)return;
 let tasks=eventTasks(id),members=eventMembers(id),orgs=members.filter(m=>m.event_role==='organizer'),manager=canManageEvent(id),canPeople=canManagePeople(id),canCreate=canCreateActivity(id);
 const statusClass='event-status-'+e.status;
 modal(`${sheetHead(e.name,`${fmtDate(e.start_date)}${e.end_date!==e.start_date?' → '+fmtDate(e.end_date):''}`)}
   <section class="event-overview">
     <div class="event-status-card ${statusClass}"><span>Estado</span><strong>${esc(EVENT_STATUS_LABEL[e.status]||e.status)}</strong>${e.status==='cancelled'?'<small>El sábado sigue guardado; podés reactivarlo editando el estado.</small>':''}</div>
     <div class="event-people-card"><span>Coordina</span><div class="event-organizers">${orgs.length?orgs.map(m=>`<button class="personLink" data-person-open="${m.person_id}">${avatarHtml(m.person_id)}<span>${esc(displayName(m.person_id))}</span></button>`).join(''):'<small>Sin coordinadores</small>'}</div></div>
     <div class="event-people-card"><span>Equipo</span><strong>${members.length}</strong><small>${members.length===1?'persona incluida':'personas incluidas'}</small></div>
   </section>
   <div class="sectionHead event-task-head"><div><span class="eyebrow">ACTIVIDADES</span><h2>${tasks.length?tasks.length+' cargadas':'Todavía no hay actividades'}</h2></div>${canPeople||canCreate?`<div class="actions">${canPeople?'<button class="btn" id="manageEventMembers">Personas</button>':''}${canCreate?'<button class="btn" id="suggestTask">Sugerencias</button><button class="btn primary" id="newTask">+ Actividad</button>':''}</div>`:''}</div>
   ${tasks.length?`<div class="list">${tasks.map(t=>taskRow(t,myAssignment(t))).join('')}</div>`:`<div class="event-empty"><div class="event-empty-icon">＋</div><h3>${e.kind==='saturday'?'Armá este sábado desde acá':'Armá este encuentro desde acá'}</h3><p>Agregá bienvenida, juegos, palabra, merienda o cualquier actividad. ${e.kind==='saturday'?'La fecha ya está tomada del sábado.':'El cronograma se va armando a medida que agregás actividades.'}</p>${canCreate?'<button class="btn primary" id="newTaskEmpty">Agregar primera actividad</button>':''}</div>`}
 `,true);
 $$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));
 $$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));
 $('#manageEventMembers')?.addEventListener('click',()=>eventMembersModal(id));
 $('#newTask')?.addEventListener('click',()=>taskEditModal(null,id));
 $('#newTaskEmpty')?.addEventListener('click',()=>taskEditModal(null,id));
 $('#suggestTask')?.addEventListener('click',()=>taskSuggestionModal(id));
}

function dayModal(d=null){let e=eventBy(S.selectedEvent),days=eventDays(e.id);modal(`${sheetHead(d?'Editar día':'Agregar día')}<form class="form" id="dayForm"><div class="field"><label>Nombre</label><input name="label" value="${esc(d?.label||`Día ${days.length+1}`)}" placeholder="Día 1 / Viernes" required></div><div class="field"><label>Fecha</label><input type="date" name="date" value="${esc(d?.date||'')}"></div><button class="btn primary">Guardar</button></form>`);$('#dayForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={event_id:e.id,label:f.get('label'),date:f.get('date')||null,sort_order:d?.sort_order??days.length};let q=d?sb.from('tnt_schedule_days').update(payload).eq('id',d.id):sb.from('tnt_schedule_days').insert(payload).select().single();let {data,error}=await q;if(error)return toast(errMsg(error));closeModal();await loadAll();S.selectedDay=d?.id||data?.id;render()}}


/* organizacion/org3b.js */
function scheduleItemModal(item=null){let d=dayBy(item?.day_id||S.selectedDay),e=eventBy(d?.event_id);if(!d||!e)return;let selected=item?itemPeople(item.id):[];let pool=[...new Set([...staffPeople().map(p=>p.id),...selected])];modal(`${sheetHead(item?'Editar actividad':'Nueva actividad',d.label)}<form class="form" id="itemForm"><div class="formRow"><div class="field"><label>Nombre</label><input name="title" value="${esc(item?.title||'')}" required></div><div class="field" data-program-extra><label>Tipo</label><select name="type">${Object.entries(ITEM_TYPE_LABEL).map(([value,label])=>`<option value="${value}" ${(item?.item_type||'activity')===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="formRow three"><div class="field"><label>Hora</label><input type="time" name="time" value="${esc(item?.starts_at?.slice(0,5)||'')}"></div><div class="field"><label>Duración (min)</label><input type="number" name="duration" min="0" value="${esc(item?.duration_minutes||'')}"></div><div class="field" data-program-extra><label>Lugar</label><input name="location" value="${esc(item?.location||'')}"></div></div><div class="field" data-program-extra><label>Descripción / instrucciones</label><textarea name="description">${esc(item?.description||'')}</textarea></div><div class="field" data-program-extra><label>Video explicativo (YouTube)</label><input name="video" value="${esc(item?.video_url||'')}" placeholder="https://youtube.com/..."></div><div class="field" data-program-extra><label>Materiales</label><textarea name="materials">${esc(item?.materials||'')}</textarea></div><label class="checkRow"><input id="program-advanced" type="checkbox" ${item?.description||item?.video_url||item?.materials||item?.location?'checked':''}> Añadir instrucciones, enlace o materiales</label><div class="field"><label>Responsables de la actividad</label><div class="checkList">${pool.map(id=>`<label class="checkRow responsible-picker"><input type="checkbox" name="person" value="${id}" ${selected.includes(id)?'checked':''}>${avatarHtml(id)}<span>${esc(displayName(id))}</span><small>${esc(aByPid(id)?.ministry_role||'')}</small></label>`).join('')}</div></div><button class="btn primary">Guardar</button></form>`);const advanced=$('#program-advanced');function toggleExtra(){$$('[data-program-extra]').forEach(el=>el.hidden=!advanced.checked)}advanced.onchange=toggleExtra;toggleExtra();$('#itemForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={day_id:d.id,title:f.get('title'),item_type:f.get('type'),starts_at:f.get('time')||null,duration_minutes:Number(f.get('duration'))||null,location:f.get('location')||null,description:f.get('description')||null,video_url:f.get('video')||null,materials:f.get("materials")||null,sort_order:item?.sort_order??dayItems(d.id).length};const r=await sb.rpc('tnt_save_schedule_item',{p_id:item?.id||null,p_day:d.id,p_values:payload,p_people:f.getAll('person')});if(r.error)return toast(errMsg(r.error));closeModal();await loadAll();render()}}
function youtubeEmbed(url){try{let u=new URL(url),id=u.hostname.includes('youtu.be')?u.pathname.slice(1):u.searchParams.get('v');return id?`<iframe style="width:100%;aspect-ratio:16/9;border:0;border-radius:16px" src="https://www.youtube.com/embed/${encodeURIComponent(id)}" allowfullscreen></iframe>`:''}catch{return''}}
function scheduleItemDetailModal(id){let i=S.items.find(x=>x.id===id),d=dayBy(i?.day_id),e=eventBy(d?.event_id);if(!i||!e)return;let rp=itemPeople(i.id);modal(`${sheetHead(i.title,`${d.label} · ${fmtTime(i.starts_at)}${i.duration_minutes?' · '+i.duration_minutes+' min':''}`)}${i.video_url?youtubeEmbed(i.video_url):''}<div class="grid g2" style="margin-top:13px"><div class="card"><h3>Responsables</h3><div class="responsibles">${rp.map(pid=>`<button class="personLink" data-person-open="${pid}">${avatarHtml(pid)} ${esc(displayName(pid))}</button>`).join('')||'<span class="tiny">Sin asignar</span>'}</div></div><div class="card"><h3>Estado en vivo</h3><div class="chips">${runChip(i.run_status||'pending')}</div></div></div><div class="card" style="margin-top:12px"><h3>Instrucciones</h3><p>${esc(i.description||'Sin descripción')}</p>${i.materials?`<h3 style="margin-top:14px">Materiales</h3><p>${esc(i.materials)}</p>`:''}${i.location?`<p><b>Lugar:</b> ${esc(i.location)}</p>`:''}</div>${canManageEvent(e.id)?`<div class="actions" style="margin-top:13px"><button class="btn" id="editItem">Editar</button><button class="btn danger" id="deleteItem">Eliminar</button></div>`:''}`);$$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));$('#editItem')?.addEventListener('click',()=>scheduleItemModal(i));$('#deleteItem')?.addEventListener('click',async()=>{if(!await U.confirm('¿Eliminar esta actividad del cronograma?'))return;let {error}=await (i.task_id?sb.rpc('tnt_delete_activity',{p_task:i.task_id}):sb.from('tnt_schedule_items').delete().eq('id',i.id));if(error)return toast(errMsg(error));closeModal();await loadAll();render()})}
async function cycleRunStatus(id){let i=S.items.find(x=>x.id===id),next=i.run_status==='pending'?'live':i.run_status==='live'?'done':'pending';let {error}=await sb.from('tnt_schedule_items').update({run_status:next}).eq('id',id);if(error)return toast(errMsg(error));await loadAll();render()}

function eventMembersModal(eventId){
 const e=eventBy(eventId),current=eventMembers(eventId),map=new Map(current.map(m=>[m.person_id,m]));
 const organizers=current.filter(m=>m.event_role==='organizer'),lockSelf=organizers.length===1&&organizers[0]?.person_id===currentPersonId()&&!isAdmin()&&!TNT.canAction?.('organizacion','manage_people','*');
 const showGroups=e.kind!=='saturday';
 modal(`${sheetHead(e.kind==='saturday'?'Personas del sábado':'Personas del evento',e.kind==='saturday'?'Elegí quién forma parte y quién coordina. Puede haber más de un coordinador.':'Elegí participantes y coordinadores.')}`
   +`<form class="form member-manager" id="membersForm">
      <div class="member-role-guide"><b>Cómo funciona</b><span>Primero incluís a la persona. Después elegís si <strong>participa</strong> o <strong>coordina</strong>. Si no está incluida, su función no se guarda.</span></div>
      <div class="checkList">${staffPeople().map(p=>{const m=map.get(p.id),locked=lockSelf&&p.id===currentPersonId(),label=esc(displayName(p.id)),included=!!m||locked,role=(locked?'organizer':m?.event_role)||'participant';return `
        <article class="member-card ${included?'is-included':''}" data-member-row="${p.id}">
          <label class="member-main">
            <input type="checkbox" name="person" value="${p.id}" ${included?'checked':''} ${locked?'disabled':''} aria-label="Incluir a ${label}">
            ${avatarHtml(p.id)}
            <span><b>${label}</b><small>${esc(aByPid(p.id)?.ministry_role||'Equipo TNT')}</small></span>
          </label>
          <div class="member-role-choice" role="group" aria-label="Función de ${label}">
            <label><input type="radio" name="role_${p.id}" value="participant" ${role==='participant'?'checked':''} ${included&&!locked?'':'disabled'}><span>Participa</span></label>
            <label><input type="radio" name="role_${p.id}" value="organizer" ${role==='organizer'?'checked':''} ${included&&!locked?'':'disabled'}><span>Coordina</span></label>
          </div>
          ${showGroups?`<label class="member-groups"><input type="checkbox" name="games_${p.id}" ${m?.include_in_groups!==false?'checked':''} ${included?'':'disabled'}> Incluir en grupos</label>`:''}
        </article>`}).join('')}</div>
      <button class="btn primary member-save" type="submit">Guardar personas</button>
    </form>`,true);
 const form=$('#membersForm');
 const syncRow=row=>{
   const check=row.querySelector('input[name="person"]'),enabled=check.checked;
   row.classList.toggle('is-included',enabled);
   row.querySelectorAll('.member-role-choice input').forEach(x=>{if(!x.closest('article').querySelector('input[name="person"]').disabled)x.disabled=!enabled;});
   const groups=row.querySelector('.member-groups input');if(groups)groups.disabled=!enabled;
 };
 form.querySelectorAll('[data-member-row]').forEach(row=>{syncRow(row);const c=row.querySelector('input[name="person"]');c.addEventListener('change',()=>syncRow(row));});
 form.onsubmit=async ev=>{
   ev.preventDefault();
   const submit=ev.target.querySelector('[type=submit]');submit.disabled=true;
   const fd=new FormData(ev.target),ids=fd.getAll('person');if(lockSelf&&!ids.includes(currentPersonId()))ids.push(currentPersonId());
   const rows=ids.map(person_id=>({event_id:eventId,person_id,event_role:(lockSelf&&person_id===currentPersonId())?'organizer':(fd.get('role_'+person_id)||'participant'),include_in_groups:showGroups?fd.get('games_'+person_id)==='on':false}));
   try{
     const r=await sb.rpc('tnt_save_event_members',{p_event:eventId,p_members:rows});if(r.error)throw r.error;
     clearOrgModal();await loadAll();render();toast('Personas actualizadas');
   }catch(error){toast(errMsg(error));submit.disabled=false;}
 };
}


