function groupConfigModal(dayId){let d=dayBy(dayId),e=eventBy(d?.event_id);if(!d||!e)return;let cfg=S.groupConfigs.find(c=>c.event_id===e.id&&c.day_id===d.id),existing=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id).sort((a,b)=>a.sort_order-b.sort_order),count=cfg?.group_count||Math.max(2,existing.length||2),names=existing.length?existing.map(g=>g.name).join('\n'):['Rojo','Azul'].join('\n'),colors=existing.length?existing.map(g=>g.color).join('\n'):['#e5484d','#3b82f6'].join('\n');modal(`${sheetHead('Configurar grupos',d.label)}<form class="form" id="groupForm"><div class="field"><label>Cantidad de equipos</label><input type="number" name="count" min="2" max="8" value="${count}"></div><div class="formRow"><div class="field"><label>Nombres (uno por línea)</label><textarea name="names">${esc(names)}</textarea></div><div class="field"><label>Colores HEX (uno por línea)</label><textarea name="colors">${esc(colors)}</textarea></div></div><label class="checkRow"><input type="checkbox" name="age" ${cfg?.balance_age===false?'':'checked'}><span>Equilibrar edades</span></label><label class="checkRow"><input type="checkbox" name="sex" ${cfg?.balance_sex===false?'':'checked'}><span>Equilibrar sexo confirmado</span></label><label class="checkRow"><input type="checkbox" name="rotate" ${cfg?.avoid_previous_day===false?'':'checked'}><span>Evitar repetir equipo del día anterior</span></label><div class="warning">La app nunca infiere sexo por el nombre. Si falta sexo o fecha de nacimiento, te lo va a pedir antes de generar.</div><button class="btn primary">Generar equipos</button></form>`);$('#groupForm').onsubmit=e2=>generateGroups(e2,e,d,cfg)}
async function generateGroups(ev,e,d,cfg){ev.preventDefault();let f=new FormData(ev.target),count=Math.max(2,Math.min(8,Number(f.get('count'))||2)),names=String(f.get('names')||'').split(/\n+/).map(s=>s.trim()).filter(Boolean),colors=String(f.get('colors')||'').split(/\n+/).map(s=>s.trim()).filter(Boolean),balanceAge=f.get('age')==='on',balanceSex=f.get('sex')==='on',rotate=f.get('rotate')==='on';while(names.length<count)names.push(`Equipo ${names.length+1}`);while(colors.length<count)colors.push(['#e5484d','#3b82f6','#8b5cf6','#10b981','#f59e0b','#ec4899'][colors.length%6]);let pool=eventMembers(e.id).filter(m=>m.include_in_groups!==false).map(m=>pBy(m.person_id)).filter(Boolean);let missing=[];pool.forEach(p=>{if(balanceSex&&(!p.sex||p.sex==='U'))missing.push(displayName(p.id)+' (sexo)');if(balanceAge&&!p.birthday)missing.push(displayName(p.id)+' (nacimiento)')});if(missing.length)return toast('Faltan datos: '+missing.slice(0,4).join(', ')+(missing.length>4?'…':''));
  let payload={event_id:e.id,day_id:d.id,group_count:count,balance_age:balanceAge,balance_sex:balanceSex,avoid_previous_day:rotate,updated_by:currentPersonId()};let qr=cfg?await sb.from('tnt_group_configs').update(payload).eq('id',cfg.id):await sb.from('tnt_group_configs').insert(payload);if(qr.error)return toast(errMsg(qr.error));
  let old=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id);if(old.length){let del=await sb.from('tnt_groups').delete().in('id',old.map(g=>g.id));if(del.error)return toast(errMsg(del.error))}
  let {data:newGroups,error:ge}=await sb.from('tnt_groups').insert([...Array(count)].map((_,i)=>({event_id:e.id,day_id:d.id,name:names[i],color:colors[i],sort_order:i}))).select();if(ge)return toast(errMsg(ge));newGroups.sort((a,b)=>a.sort_order-b.sort_order);
  let days=eventDays(e.id),idx=days.findIndex(x=>x.id===d.id),prev=idx>0?days[idx-1]:null,prevMap=new Map();if(prev){let pgs=S.groups.filter(g=>g.event_id===e.id&&g.day_id===prev.id);for(let g of pgs)for(let m of S.groupMembers.filter(x=>x.group_id===g.id))prevMap.set(m.person_id,g.name)}
  let persons=pool.map(p=>({p,age:age(p.birthday,d.date?new Date(d.date+'T12:00:00'):new Date()),sex:p.sex||'U'}));persons.sort((a,b)=>(a.sex||'').localeCompare(b.sex||'')||((b.age||0)-(a.age||0)));let teams=newGroups.map(g=>({g,people:[],ageSum:0,sex:{F:0,M:0,U:0}}));let targetAvg=persons.length?persons.reduce((s,x)=>s+(x.age||0),0)/persons.length:0;
  for(let x of persons){let scored=teams.map(t=>{let size=t.people.length,score=size*100;if(balanceSex)score+=(t.sex[x.sex]||0)*35;if(balanceAge&&x.age!=null){let avg=(t.ageSum+x.age)/(size+1);score+=Math.abs(avg-targetAvg)*4}if(rotate&&prevMap.get(x.p.id)===t.g.name)score+=75;return{t,score}}).sort((a,b)=>a.score-b.score);let t=scored[0].t;t.people.push(x);t.ageSum+=x.age||0;t.sex[x.sex]=(t.sex[x.sex]||0)+1}
  let rows=[];teams.forEach(t=>t.people.forEach(x=>rows.push({group_id:t.g.id,person_id:x.p.id,age_snapshot:x.age,sex_snapshot:x.sex})));if(rows.length){let ir=await sb.from('tnt_group_members').insert(rows);if(ir.error)return toast(errMsg(ir.error))}closeModal();await loadAll();render();toast('Equipos generados')}
async function moveGroupMember(personId,fromId,toId){if(fromId===toId)return;let old=S.groupMembers.find(m=>m.group_id===fromId&&m.person_id===personId);let d=await sb.from('tnt_group_members').delete().eq('group_id',fromId).eq('person_id',personId);if(d.error)return toast(errMsg(d.error));let i=await sb.from('tnt_group_members').insert({group_id:toId,person_id:personId,age_snapshot:old?.age_snapshot,sex_snapshot:old?.sex_snapshot});if(i.error)return toast(errMsg(i.error));await loadAll();render()}



/* organizacion/org4b.js */
function taskEditModal(task=null,eventId=S.selectedEvent,parentId=null,suggestion=null){
 let e=eventBy(eventId),manager=task?canEditActivity(eventId):canCreateActivity(eventId);if(!manager){toast('No tenés permiso para '+(task?'editar':'crear')+' actividades.');return;}
 let selected=task?taskPeople(task.id):[];const draft=task||suggestion||{};
 let pool=[...new Set([...staffPeople().map(p=>p.id),...selected])];
 const initialMode=draft.assignee_mode||(selected.length>1?'multiple':'single');
 const saturday=e?.kind==='saturday';
 const startValue=task?.planned_start?(saturday?U.time(task.planned_start):U.dateKey(task.planned_start)+'T'+U.time(task.planned_start)):'';
 modal(`${sheetHead(task?'Editar actividad':'Nueva actividad',e?.name||'')}
 <form class="form task-editor" id="taskForm">
   <div class="formRow"><div class="field"><label>Nombre</label><input name="title" value="${esc(draft.title||'')}" required></div><div class="field"><label>Tipo</label><select name="type"><option value="simple" ${draft.task_type==='simple'?'selected':''}>Simple</option><option value="complex" ${draft.task_type==='complex'?'selected':''}>Dinámica / con instrucciones</option><option value="logistics" ${draft.task_type==='logistics'?'selected':''}>Área de trabajo / logística</option></select></div></div>
   <div class="formRow three" data-task-detail><div class="field"><label>Prioridad</label><select name="priority">${Object.entries(PRIORITY_LABEL).map(([value,label])=>`<option value="${value}" ${task?.priority===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Fecha límite</label><input type="datetime-local" name="due" value="${task?.due_at?U.dateKey(task.due_at)+'T'+U.time(task.due_at):''}"></div><div class="field"><label>Presupuesto estimado</label><input type="number" name="budget" min="0" step="1" value="${esc(draft.budget_estimated||'')}"></div></div>
   <div class="formRow"><div class="field"><label>Horario de la actividad</label>${saturday?`<div class="fixed-date-field"><span>${fmtDate(e.start_date)}</span><input type="time" name="start" value="${startValue}"></div><small>La fecha la toma automáticamente del sábado.</small>`:`<input type="datetime-local" name="start" value="${startValue}"><small>Debe quedar dentro de las fechas del evento.</small>`}</div><div class="field"><label>Duración (minutos)</label><input type="number" name="duration" min="1" max="1440" value="${esc(draft.duration_minutes||'')}"></div></div>
   <div class="field" data-task-detail><label>Descripción / planificación</label><textarea name="description">${esc(draft.description||'')}</textarea></div>
   <div class="field" data-task-detail><label>Materiales necesarios</label><textarea name="materials">${esc(draft.materials||'')}</textarea></div>
   <fieldset class="responsibility-box"><legend>¿Cuántas personas necesita?</legend><div class="responsibility-options"><label><input type="radio" name="assignee_mode" value="single" ${initialMode==='single'?'checked':''}><span>Una persona</span></label><label><input type="radio" name="assignee_mode" value="multiple" ${initialMode==='multiple'?'checked':''}><span>Varias personas</span></label></div><small id="responsibilityHint">Si elegís una persona, cuando ya haya una asignada las demás quedan bloqueadas.</small></fieldset>
   <div class="field"><label>¿Quién se encarga?</label><div class="checkList assignee-list">${pool.map(pid=>{let w=workloadFor(pid),av=e?.start_date?S.availability.find(a=>a.person_id===pid&&a.date===e.start_date):null;return `<label class="checkRow responsible-picker"><input type="checkbox" name="assignee" value="${pid}" ${selected.includes(pid)?'checked':''}>${avatarHtml(pid)}<span>${esc(displayName(pid))}${av?.status==='unavailable'?'<div class="dangerText tiny">No disponible ese día</div>':av?.status==='maybe'?'<div class="tiny">Disponibilidad dudosa</div>':''}</span><small>${w} asign. este mes</small></label>`}).join('')}</div></div>
   <div class="field" data-task-detail><label>Enlace de referencia</label><input type="url" name="reference" value="${esc(draft.reference_url||'')}" placeholder="https://"></div>
   <div class="field" data-task-detail><label>Archivo para compartir</label><input type="file" name="file"></div>
   <button class="btn primary" type="submit">Guardar actividad</button>
 </form>`,true);
 let savedTaskId=task?.id||null,savedReference='',savedAttachment=false,savedChecklist=false;
 const taskForm=$('#taskForm');
 function adjust(){
   const kind=taskForm.elements.type.value;
   taskForm.querySelectorAll('[data-task-detail]').forEach(el=>el.hidden=kind==='simple');
   const budget=taskForm.querySelector('[name=budget]')?.closest('.field');if(budget)budget.hidden=kind!=='logistics';
 }
 function syncAssignees(){
   const single=taskForm.elements.assignee_mode.value==='single',boxes=[...taskForm.querySelectorAll('input[name="assignee"]')],checked=boxes.filter(x=>x.checked);
   if(single&&checked.length>1){checked.slice(1).forEach(x=>x.checked=false);}
   const active=boxes.find(x=>x.checked);
   boxes.forEach(x=>{x.disabled=single&&!!active&&!x.checked;x.closest('.checkRow')?.classList.toggle('is-disabled',x.disabled);});
   $('#responsibilityHint').textContent=single?(active?'Ya hay una persona asignada. Desmarcala para elegir otra.':'Elegí una sola persona responsable.'):'Podés elegir todas las personas que realmente necesite la actividad.';
 }
 taskForm.elements.type.onchange=adjust;
 taskForm.querySelectorAll('input[name="assignee_mode"]').forEach(x=>x.onchange=syncAssignees);
 taskForm.querySelectorAll('input[name="assignee"]').forEach(x=>x.onchange=syncAssignees);
 adjust();syncAssignees();
 taskForm.onsubmit=async ev=>{
   ev.preventDefault();let fd=new FormData(ev.target);
   const startRaw=String(fd.get('start')||'');
   const plannedStart=startRaw?(saturday?new Date(e.start_date+'T'+startRaw+':00-03:00').toISOString():new Date(startRaw+'-03:00').toISOString()):null;
   const payload={event_id:eventId,parent_task_id:parentId||task?.parent_task_id||null,title:fd.get('title'),task_type:fd.get('type'),priority:fd.get('priority'),description:fd.get('description')||null,materials:fd.get('materials')||null,due_at:fd.get('due')?new Date(fd.get('due')+'-03:00').toISOString():null,planned_start:plannedStart,duration_minutes:Number(fd.get('duration'))||null,budget_estimated:Number(fd.get('budget'))||null,assignee_mode:fd.get('assignee_mode')||'single',created_by:task?.created_by||currentPersonId(),sort_order:task?.sort_order??S.tasks.filter(t=>t.event_id===eventId).length};
   if(payload.task_type==='simple'){Object.assign(payload,{priority:'medium',description:null,materials:null,due_at:null,budget_estimated:null});}else if(payload.task_type!=='logistics')payload.budget_estimated=null;
   const btn=ev.target.querySelector('[type=submit]');btn.disabled=true;
   try{
     const r=await sb.rpc('tnt_save_task',{p_id:savedTaskId,p_event:eventId,p_values:payload,p_people:fd.getAll('assignee')});if(r.error)throw r.error;savedTaskId=r.data;
     const reference=String(fd.get('reference')||'').trim();if(reference&&reference!==savedReference&&payload.task_type!=='simple'){const l=await sb.from('tnt_task_links').insert({task_id:r.data,url:reference,label:'Referencia',link_type:linkType(reference),sort_order:0});if(l.error)throw l.error;savedReference=reference;}
     const file=fd.get('file');if(file?.size&&!savedAttachment&&payload.task_type!=='simple'){const safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,'_'),storagePath=`${r.data}/${currentPersonId()}/${Date.now()}-${safe}`,up=await sb.storage.from('tnt-files').upload(storagePath,file,{upsert:false});if(up.error)throw up.error;const meta=await sb.from('tnt_task_files').insert({task_id:r.data,storage_path:storagePath,file_name:file.name,mime_type:file.type,size_bytes:file.size,uploaded_by:currentPersonId()});if(meta.error){await sb.storage.from('tnt-files').remove([storagePath]);throw meta.error;}savedAttachment=true;}
     if(suggestion?.checklist?.length&&!savedChecklist&&payload.task_type!=='simple'){const rows=suggestion.checklist.map((text,sort_order)=>({task_id:r.data,text,sort_order}));const check=await sb.from('tnt_task_checklist').insert(rows);if(check.error)throw check.error;savedChecklist=true;}
     closeModal();await loadAll();render();toast('Actividad guardada');taskDetailModal(r.data);
   }catch(error){toast(errMsg(error));btn.disabled=false;}
 };
}

function taskSuggestionModal(eventId){const e=eventBy(eventId),templates=S.templates.filter(t=>e.activity_type_id?t.id===e.activity_type_id:t.kind===e.kind),items=templates.flatMap(t=>S.templateItems.filter(i=>i.template_id===t.id).map(i=>({...i,templateName:t.name})));const o=U.modal('Sugerencias para '+e.name,`<p>Son ideas, no tareas creadas. Elegí una, adaptá instrucciones y responsables, y recién entonces guardala.</p><div class="list">${items.map(i=>`<button type="button" class="rowCard" data-suggest="${i.id}"><div class="ico">${esc(i.icon||'✓')}</div><div><b>${esc(i.title)}</b><div class="tiny">${esc(i.templateName)} · ${esc(i.description||'Agregá instrucciones antes de usarla')}</div></div></button>`).join('')||'<p>Sin sugerencias para este tipo. Podés crear una tarea desde cero.</p>'}</div>`);o.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=async()=>{await U.closeModal(o);taskEditModal(null,eventId,null,items.find(i=>i.id===b.dataset.suggest));});}
function addChecklistModal(taskId,order){modal(`${sheetHead('Agregar punto')}<form class="form" id="checkForm"><div class="field"><label>Texto</label><input name="text" required></div><button class="btn primary">Agregar</button></form>`);$('#checkForm').onsubmit=async ev=>{ev.preventDefault();let text=new FormData(ev.target).get('text');let {error}=await sb.from('tnt_task_checklist').insert({task_id:taskId,text,sort_order:order});if(error)return toast(errMsg(error));taskDetailModal(taskId)}}
function linkType(url){try{let h=new URL(url).hostname;if(h.includes('youtu'))return'youtube';if(h.includes('pinterest'))return'pinterest';if(h.includes('instagram'))return'instagram';if(h.includes('drive.google'))return'drive';if(h.includes('canva'))return'canva'}catch{}return'link'}
function addLinkModal(taskId,order){modal(`${sheetHead('Agregar referencia')}<form class="form" id="linkForm"><div class="field"><label>URL</label><input name="url" type="url" required></div><div class="field"><label>Etiqueta</label><input name="label" placeholder="Referencia"></div><button class="btn primary">Agregar</button></form>`);$('#linkForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),url=f.get('url');let {error}=await sb.from('tnt_task_links').insert({task_id:taskId,url,label:f.get('label')||null,link_type:linkType(url),sort_order:order});if(error)return toast(errMsg(error));taskDetailModal(taskId)}}
function linkCard(l){let thumb='🔗',img='';if(l.link_type==='youtube'){thumb='▶';try{let u=new URL(l.url),id=u.hostname.includes('youtu.be')?u.pathname.slice(1):u.searchParams.get('v');if(id)img=`https://i.ytimg.com/vi/${encodeURIComponent(id)}/hqdefault.jpg`}catch{}}else if(l.link_type==='pinterest')thumb='📌';else if(l.link_type==='instagram')thumb='📷';else if(l.link_type==='drive')thumb='📄';else if(l.link_type==='canva')thumb='🎨';return `<a class="linkPreview" href="${esc(l.url)}" target="_blank" rel="noopener">${img?`<img src="${img}" alt="">`:`<div class="linkThumb">${thumb}</div>`}<div><b>${esc(l.label||l.link_type)}</b><small>${esc(l.url)}</small></div><span class="arr">›</span></a>`}
async function uploadTaskFile(taskId,file){if(!file)return;let safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,'_'),path=`${taskId}/${currentPersonId()}/${Date.now()}-${safe}`;let up=await sb.storage.from('tnt-files').upload(path,file,{upsert:false});if(up.error)return toast(errMsg(up.error));let r=await sb.from('tnt_task_files').insert({task_id:taskId,storage_path:path,file_name:file.name,mime_type:file.type,size_bytes:file.size,uploaded_by:currentPersonId()});if(r.error)return toast(errMsg(r.error));toast('Archivo subido');taskDetailModal(taskId)}
async function openTaskFile(path){let {data,error}=await sb.storage.from('tnt-files').createSignedUrl(path,300);if(error)return toast(errMsg(error));window.open(data.signedUrl,'_blank','noopener')}
function addPrivateNoteModal(taskId){modal(`${sheetHead('Nota privada','Solo organizadores / Pastor / Admin')}<form class="form" id="privateForm"><div class="field"><textarea name="body" required></textarea></div><button class="btn primary">Guardar</button></form>`);$('#privateForm').onsubmit=async ev=>{ev.preventDefault();let body=new FormData(ev.target).get('body');let {error}=await sb.from('tnt_task_private_notes').insert({task_id:taskId,author_person_id:currentPersonId(),body});if(error)return toast(errMsg(error));taskDetailModal(taskId)}}

async function personResponsibilitiesModal(pid){let p=pBy(pid),a=aByPid(pid);if(!p)return;let tasks=S.assignees.filter(x=>x.person_id===pid).map(x=>({a:x,t:taskBy(x.task_id)})).filter(x=>x.t),sched=S.responsibles.filter(r=>r.person_id===pid).map(r=>{let i=S.items.find(x=>x.id===r.item_id),d=dayBy(i?.day_id),e=eventBy(d?.event_id);return{i,d,e}}).filter(x=>x.i);let avail=S.availability.filter(x=>x.person_id===pid&&x.date>=today()).slice(0,6);modal(`${sheetHead(a?.nickname||p.full_name,a?.ministry_role||'')}<div class="profileHero">${avatarHtml(pid)}<div><h3 style="margin:0">${esc(p.full_name)}</h3><p class="muted" style="margin:4px 0">${p.birthday?'🎂 '+fmtDate(p.birthday):''}${p.phone?' · 📱 '+esc(p.phone):''}</p><div class="chips">${a?.service_areas?.map(x=>`<span class="chip">${esc(x)}</span>`).join('')||''}</div></div><div class="actions">${pid===currentPersonId()||isAdmin()||isPastor()?`<button class="btn small" id="editPerson">Editar perfil</button>`:''}</div></div><div class="sectionHead"><h2>Responsabilidades</h2></div>${sched.length?`<div class="list">${sched.map(x=>`<div class="rowCard"><div class="ico">◷</div><div><b>${esc(x.i.title)}</b><div class="meta">${esc(x.e?.name||'')} · ${esc(x.d?.label||'')} · ${fmtTime(x.i.starts_at)}</div></div><button class="btn small" data-item-open="${x.i.id}">Ver</button></div>`).join('')}</div>`:''}${tasks.length?`<div class="list" style="margin-top:9px">${tasks.map(({a,t})=>taskRow(t,a)).join('')}</div>`:''}${!tasks.length&&!sched.length?empty('Sin responsabilidades',''):''}<div class="sectionHead"><h2>Disponibilidad</h2>${pid===currentPersonId()?'<button class="btn small" id="addAvailability">+ Fecha</button>':''}</div>${avail.length?`<div class="chips">${avail.map(x=>`<span class="chip">${fmtShort(x.date)} · ${x.status==='available'?'Disponible':x.status==='maybe'?'Tal vez':'No puede'}</span>`).join('')}</div>`:'<div class="tiny">Sin fechas cargadas</div>'}`,true);$('#editPerson')?.addEventListener('click',()=>profileModal(pid));$('#addAvailability')?.addEventListener('click',()=>availabilityModal(pid));$$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));$$('[data-item-open]').forEach(b=>b.onclick=()=>scheduleItemDetailModal(b.dataset.itemOpen))}



