function profileModal(pid=currentPersonId(),isNew=false){let p=pid?pBy(pid):null,a=pid?aByPid(pid):null,self=pid===currentPersonId(),roleEdit=isAdmin();let prefs=a?.service_preferences||{};modal(`${sheetHead(isNew?'Nuevo perfil':'Perfil TNT',isNew?'Podés precargar el email antes de que la persona ingrese con Google.':'Datos centrales compartibles con otros módulos')}<form class="form" id="profileForm"><div class="profileHero">${p?avatarHtml(p.id):'<div class="avatar">+</div>'}<div><b>${esc(a?.nickname||p?.full_name||'Nuevo perfil')}</b><div class="tiny">${esc(a?.system_role==='admin'?'Admin · '+a?.ministry_role:a?.ministry_role||'')}</div></div>${p&&(self||isAdmin())?'<label class="btn small">Cambiar foto<input id="avatarFile" type="file" accept="image/*" hidden></label>':''}</div><div class="formRow"><div class="field"><label>Nombre completo</label><input name="name" value="${esc(p?.full_name||'')}" required></div><div class="field"><label>Sobrenombre</label><input name="nick" value="${esc(a?.nickname||'')}"></div></div><div class="formRow three"><div class="field"><label>Fecha de nacimiento</label><input type="date" name="birthday" value="${esc(p?.birthday||'')}"></div><div class="field"><label>Sexo confirmado</label><div class="org-sexo-choice"><label><input type="radio" name="sex" value="U" ${!p?.sex||p.sex==='U'?'checked':''}> Sin confirmar</label><label><input type="radio" name="sex" value="F" ${p?.sex==='F'?'checked':''}> Mujer</label><label><input type="radio" name="sex" value="M" ${p?.sex==='M'?'checked':''}> Varón</label></div></div><div class="field"><label>WhatsApp / teléfono</label><input name="phone" value="${esc(p?.phone||'')}"></div></div><div class="field"><label>Email de cuenta</label><input type="email" name="email" value="${esc(a?.email||'')}"></div>${roleEdit?`<div class="field"><label>Rol TNT</label><select name="role">${ROLE_OPTIONS.map(r=>`<option value="${r}" ${a?.ministry_role===r?'selected':''}>${r}</option>`).join('')}</select></div>`:''}<div class="field"><label>Áreas en las que sirve / le gusta servir</label><div class="checkList">${SERVICE_AREAS.map(x=>`<label class="checkRow"><input type="checkbox" name="area" value="${esc(x)}" ${a?.service_areas?.includes(x)?'checked':''}><span>${esc(x)}</span><select name="pref_${esc(x)}"><option value="neutral" ${(prefs[x]||'neutral')==='neutral'?'selected':''}>Me da igual</option><option value="love" ${prefs[x]==='love'?'selected':''}>Me encanta</option><option value="avoid" ${prefs[x]==='avoid'?'selected':''}>Prefiero no hacerlo</option></select></label>`).join('')}</div></div><div class="field"><label>Talentos / habilidades</label><input name="skills" value="${esc((a?.skills||[]).join(', '))}" placeholder="Fotografía, video, diseño"></div><div class="field"><label>Disponibilidad habitual</label><input name="days" value="${esc((a?.availability_days||[]).join(', '))}" placeholder="Sábados, Miércoles"></div><div class="field"><label>Sobre mí</label><textarea name="bio">${esc(a?.bio||'')}</textarea></div><div class="field"><label>Información personal extra (opcional)</label><textarea name="extra" placeholder="Campo: valor, uno por línea">${esc(Object.entries(a?.profile_extra||{}).map(([k,v])=>`${k}: ${v}`).join('\n'))}</textarea></div><button class="btn primary">Guardar perfil</button></form>`,true);
  $('#avatarFile')?.addEventListener('change',e=>uploadAvatar(pid,e.target.files?.[0]));$('#profileForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),personPayload={full_name:String(f.get('name')).trim(),normalized_name:String(f.get('name')).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,''),birthday:f.get('birthday')||null,sex:f.get('sex')||'U',phone:f.get('phone')||null,source:p?.source||'organizacion',active:true};let personId=pid;if(isNew){let ins=await sb.from('tnt_people').insert(personPayload).select().single();if(ins.error)return toast(errMsg(ins.error));personId=ins.data.id}else{let u=await sb.from('tnt_people').update(personPayload).eq('id',personId);if(u.error)return toast(errMsg(u.error))}let pref={};SERVICE_AREAS.forEach(x=>pref[x]=f.get('pref_'+x)||'neutral');let extra={};String(f.get('extra')||'').split(/\n+/).forEach(line=>{let i=line.indexOf(':');if(i>0)extra[line.slice(0,i).trim()]=line.slice(i+1).trim()});let accountPayload={person_id:personId,email:f.get('email')||null,nickname:f.get('nick')||null,service_areas:f.getAll('area'),skills:String(f.get('skills')||'').split(',').map(x=>x.trim()).filter(Boolean),availability_days:String(f.get('days')||'').split(',').map(x=>x.trim()).filter(Boolean),service_preferences:pref,bio:f.get('bio')||null,profile_extra:extra};if(roleEdit){accountPayload.ministry_role=f.get('role');accountPayload.staff_status='approved';accountPayload.staff_reviewed_at=new Date().toISOString();accountPayload.staff_reviewed_by=currentPersonId();}if(a){let u=await sb.from('tnt_accounts').update(accountPayload).eq('person_id',personId);if(u.error)return toast(errMsg(u.error))}else{accountPayload.ministry_role=roleEdit?f.get('role'):'Timoteo';let ins=await sb.from('tnt_accounts').insert(accountPayload);if(ins.error)return toast(errMsg(ins.error))}closeModal();await loadAll();render();toast('Perfil guardado')}}
async function uploadAvatar(pid,file){if(!file)return;let safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,'_'),path=`${pid}/${Date.now()}-${safe}`;let up=await sb.storage.from('tnt-avatars').upload(path,file,{upsert:false});if(up.error)return toast(errMsg(up.error));let {data}=sb.storage.from('tnt-avatars').getPublicUrl(path);let u=await sb.from('tnt_accounts').update({avatar_url:data.publicUrl}).eq('person_id',pid);if(u.error)return toast(errMsg(u.error));await loadAll();profileModal(pid);toast('Foto actualizada')}
function availabilityModal(pid){modal(`${sheetHead('Disponibilidad puntual')}<form class="form" id="avForm"><div class="field"><label>Fecha</label><input type="date" name="date" required></div><div class="field"><label>Estado</label><select name="status"><option value="available">Disponible</option><option value="maybe">Probablemente no pueda</option><option value="unavailable">No puedo</option></select></div><div class="field"><label>Nota</label><input name="note"></div><button class="btn primary">Guardar</button></form>`);$('#avForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),{error}=await sb.from('tnt_availability').upsert({person_id:pid,date:f.get('date'),status:f.get('status'),note:f.get('note')||null});if(error)return toast(errMsg(error));closeModal();await loadAll();personResponsibilitiesModal(pid)}}



