function templateModal(id=null){let t=S.templates.find(x=>x.id===id),items=t?S.templateItems.filter(i=>i.template_id===id).sort((a,b)=>a.sort_order-b.sort_order):[];modal(`${sheetHead(t?'Editar plantilla':'Nueva plantilla')}<form class="form" id="tplForm"><div class="field"><label>Nombre</label><input name="name" value="${esc(t?.name||'')}" placeholder="Ej.: Evangelismo, visita a otra iglesia, congreso" required></div><div class="field"><label>Tipo</label><select name="kind"><option value="saturday" ${t?.kind==='saturday'?'selected':''}>Sábado</option><option value="event" ${t?.kind==='event'?'selected':''}>Evento</option><option value="camp" ${t?.kind==='camp'?'selected':''}>Campamento</option></select></div><div class="field"><label>Descripción</label><textarea name="description">${esc(t?.description||'')}</textarea></div><button class="btn primary">Guardar plantilla</button></form>${t?`<div class="sectionHead"><h2>Ítems</h2><button class="btn small primary" id="addTplItem">+ Ítem</button></div><div class="list">${items.map((i,idx)=>`<div class="rowCard"><div class="ico">${esc(i.icon||'✓')}</div><div><b>${esc(i.title)}</b><div class="tiny">${esc(i.description||"Sin instrucciones")}${i.duration_minutes?" · "+i.duration_minutes+" min":""}</div></div><div class="actions"><button class="btn small" data-tpl-edit="${i.id}">Editar</button><button class="btn small" data-tpl-move="${i.id}" data-dir="-1">↑</button><button class="btn small" data-tpl-move="${i.id}" data-dir="1">↓</button><button class="btn small danger" data-tpl-del="${i.id}">×</button></div></div>`).join('')}</div><div class="actions" style="margin-top:15px"><button class="btn danger" id="deleteTemplate">Eliminar plantilla</button></div>`:''}`);$('#tplForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={name:f.get('name'),kind:f.get('kind'),description:f.get('description')||null,created_by:t?.created_by||currentPersonId()};let res=t?await sb.from('tnt_templates').update(payload).eq('id',t.id).select().single():await sb.from('tnt_templates').insert(payload).select().single();if(res.error)return toast(errMsg(res.error));await loadAll();templateModal(res.data.id);toast('Plantilla guardada')};$('#addTplItem')?.addEventListener('click',()=>templateItemModal(t.id,items.length));$$('[data-tpl-edit]').forEach(b=>b.onclick=()=>templateItemModal(t.id,items.length,items.find(i=>i.id===b.dataset.tplEdit)));$$('[data-tpl-del]').forEach(b=>b.onclick=async()=>{const r=await sb.from('tnt_template_items').delete().eq('id',b.dataset.tplDel);if(r.error)return toast(errMsg(r.error));await loadAll();templateModal(t.id)});$$('[data-tpl-move]').forEach(b=>b.onclick=()=>moveTemplateItem(t.id,b.dataset.tplMove,Number(b.dataset.dir)));$('#deleteTemplate')?.addEventListener('click',async()=>{if(!await U.confirm('¿Eliminar esta plantilla?'))return;let {error}=await sb.from('tnt_templates').delete().eq('id',t.id);if(error)return toast(errMsg(error));closeModal();await loadAll();render()})}
function templateItemModal(templateId,order,item=null){
 modal(`${sheetHead(item?'Editar sugerencia':'Nueva sugerencia','Al agregarla a un sábado podrás cambiarla antes de guardarla.')}<form class="form" id="tplItemForm"><div class="formRow"><div class="field"><label>Nombre</label><input name="title" value="${esc(item?.title||'')}" required></div><div class="field"><label>Ícono</label><input name="icon" value="${esc(item?.icon||'✓')}"></div></div><div class="field"><label>Tipo</label><select name="type"><option value="simple" ${item?.task_type==='simple'?'selected':''}>Simple</option><option value="complex" ${item?.task_type==='complex'?'selected':''}>Dinámica / instrucciones</option><option value="logistics" ${item?.task_type==='logistics'?'selected':''}>Área de trabajo / logística</option></select></div><div class="field" data-template-detail><label>Instrucciones concretas</label><textarea name="description" placeholder="Qué hay que hacer, dónde y para cuándo">${esc(item?.description||'')}</textarea></div><div class="field" data-template-detail><label>Materiales</label><textarea name="materials">${esc(item?.materials||'')}</textarea></div><div class="field"><label>Duración estimada en minutos</label><input name="duration" type="number" min="1" max="1440" value="${esc(item?.duration_minutes||'')}"></div><div class="field" data-template-detail><label>Pasos para completar (uno por línea)</label><textarea name="checklist">${esc((item?.checklist||[]).join('\n'))}</textarea></div><div class="field" data-template-detail><label>Enlace de referencia</label><input type="url" name="reference" value="${esc(item?.reference_url||'')}" placeholder="https://"></div><div class="field" data-template-budget><label>Presupuesto estimado</label><input name="budget" type="number" min="0" value="${esc(item?.budget_estimated||'')}"></div><button class="btn primary">${item?'Guardar cambios':'Guardar sugerencia'}</button></form>`);
 const templateForm=$('#tplItemForm');const adjustTemplate=()=>{const kind=templateForm.elements.type.value;templateForm.querySelectorAll('[data-template-detail]').forEach(el=>el.hidden=kind==='simple');templateForm.querySelector('[data-template-budget]').hidden=kind!=='logistics';};templateForm.elements.type.onchange=adjustTemplate;adjustTemplate();
 $('#tplItemForm').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),payload={template_id:templateId,title:f.get('title'),icon:f.get('icon')||'✓',task_type:f.get('type'),description:f.get('type')==='simple'?null:f.get('description')||null,materials:f.get('type')==='simple'?null:f.get('materials')||null,reference_url:f.get('type')==='simple'?null:f.get('reference')||null,budget_estimated:f.get('type')==='logistics'?Number(f.get('budget'))||null:null,duration_minutes:Number(f.get('duration'))||null,checklist:f.get('type')==='simple'?[]:String(f.get('checklist')||'').split(/\n+/).map(x=>x.trim()).filter(Boolean),sort_order:item?.sort_order??order},r=item?await sb.from('tnt_template_items').update(payload).eq('id',item.id):await sb.from('tnt_template_items').insert(payload);if(r.error)return toast(errMsg(r.error));await loadAll();templateModal(templateId)};
}

async function moveTemplateItem(templateId,id,dir){let items=S.templateItems.filter(i=>i.template_id===templateId).sort((a,b)=>a.sort_order-b.sort_order),idx=items.findIndex(i=>i.id===id),other=items[idx+dir];if(idx<0||!other)return;let cur=items[idx];await Promise.all([sb.from('tnt_template_items').update({sort_order:other.sort_order}).eq('id',cur.id),sb.from('tnt_template_items').update({sort_order:cur.sort_order}).eq('id',other.id)]);await loadAll();templateModal(templateId)}

// Eventos globales posteriores al render





function openDeepLink(){const q=new URLSearchParams(location.search);if(q.get('task')&&taskBy(q.get('task')))taskDetailModal(q.get('task'));else if(q.get('event')&&eventBy(q.get('event')))eventDetailModal(q.get('event'));else if(q.get('person')&&pBy(q.get('person')))personResponsibilitiesModal(q.get('person'));}

function avatars(ids,max=5){return U.avatarStack(ids,S.people,S.accounts,currentPersonId(),max);}

function personalTasks(){return S.tasks.filter(t=>myAssignment(t)&&myAssignment(t).assignment_status!=='declined'&&!U.completed(t)).sort((a,b)=>(a.planned_start||a.due_at||eventBy(a.event_id)?.start_date||'9999').localeCompare(b.planned_start||b.due_at||eventBy(b.event_id)?.start_date||'9999'));}

function personalItems(){const ids=new Set(S.responsibles.filter(r=>r.person_id===currentPersonId()).map(r=>r.item_id));return S.items.filter(i=>itemPeople(i.id).includes(currentPersonId())&&i.run_status!=='done'&&(!i.task_id||!personalTasks().some(t=>t.id===i.task_id))&&dayBy(i.day_id)?.date>=today());}

function taskMatches(t){const mine=Boolean(myAssignment(t)&&myAssignment(t).assignment_status!=='declined'),d=(t.planned_start||t.due_at)?U.dateKey(t.planned_start||t.due_at):eventBy(t.event_id)?.start_date;const f=S.activityFilter||'all';if(f==='mine'&&!mine)return false;if(f==='today'&&d!==today())return false;if(f==='upcoming'&&(!d||d<today()||U.completed(t)))return false;if(f==='unread'&&(!mine||myAssignment(t).assignment_status!=='assigned'))return false;if(f==='answer'&&(!mine||!['assigned','read'].includes(myAssignment(t).assignment_status)))return false;return !S.activityEvent||t.event_id===S.activityEvent;}

function viewActivities(){const filter=S.activityFilter||'upcoming',todayKey=today();const visible=S.events.filter(e=>e.status!=='cancelled').filter(e=>filter==='past'?e.end_date<todayKey:filter==='mine'?eventTasks(e.id).some(t=>myAssignment(t)?.assignment_status!=='declined'&&myAssignment(t)):e.end_date>=todayKey).sort((a,b)=>filter==='past'?b.start_date.localeCompare(a.start_date):a.start_date.localeCompare(b.start_date));return `<div class="sectionHead"><div><h2>Actividades</h2><p>Elegí un sábado, evangelismo o evento para ver su programa y el trabajo del equipo.</p></div></div><div class="activity-tools"><div class="filters">${[['upcoming','Próximas'],['mine','Con tareas mías'],['past','Anteriores']].map(([key,label])=>`<button data-filter="${key}" class="${filter===key?'on':''}">${label}</button>`).join('')}</div></div><div class="grid g2">${visible.map(e=>{const tasks=eventTasks(e.id),pending=tasks.filter(t=>t.status==='review'&&canManageEvent(e.id)).length,assigned=tasks.filter(t=>myAssignment(t)&&myAssignment(t).assignment_status!=='declined').length,kind=e.kind==='saturday'?'Sábado':e.kind==='camp'?'Campamento':S.templates.find(t=>t.id===e.activity_type_id)?.name||'Evento';return `<button class="encounter-card" data-event-open="${e.id}"><span class="encounter-date">${fmtShort(e.start_date)}</span><span class="encounter-body"><small>${esc(kind)}</small><b>${esc(e.name)}</b><span>${tasks.length} ${tasks.length===1?'elemento':'elementos'}${assigned?' · '+assigned+' tuyos':''}${pending?' · '+pending+' piden revisión':''}</span></span>${U.icon('arrow')}</button>`}).join('')||empty(filter==='past'?'No hay actividades anteriores':'No hay actividades próximas','Creá un sábado o evento desde su sección; después agregá el programa.')}</div>`;}

function viewCalendar(){const selected=S.calendarDate||today(),month=S.calendarMonth||selected.slice(0,7)+'-01',mode=S.calendarMode||'month',start=new Date(month+'T12:00:00Z'),days=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).getUTCDate(),offset=(start.getUTCDay()+6)%7;let cells=Array.from({length:offset},()=>'<span></span>');for(let d=1;d<=days;d++){const date=month.slice(0,8)+String(d).padStart(2,'0'),events=S.events.filter(e=>e.start_date<=date&&e.end_date>=date&&e.status!=='cancelled'),mine=events.some(e=>eventMembers(e.id).some(m=>m.person_id===currentPersonId()));cells.push(`<button class="cal-day ${date===selected?'selected':''} ${date===today()?'today':''}" data-cal-date="${date}" aria-label="${fmtDate(date)}: ${events.length} eventos" aria-pressed="${date===selected}">${d}${events.length?'<span class="cal-dots"><i></i>'+(mine?'<i class="personal"></i>':'')+'</span>':''}</button>`);}const def=S.settings.find(s=>s.key==='organization_defaults')?.value||{};return `<div class="sectionHead"><h2>Calendario</h2><div class="actions"><button class="btn" data-cal-today>Hoy</button></div></div><div class="cal-modes">${[['month','Mes'],['week','Semana'],['day','Día']].map(([k,l])=>`<button data-cal-mode="${k}" class="${mode===k?'on':''}">${l}</button>`).join('')}</div><div class="calendar-layout ${mode!=='month'?'wide-agenda':''}">${mode==='month'?`<section class="calendar-panel"><div class="calendar-top"><button data-month-step="-1" aria-label="Mes anterior">${U.icon('back')}</button><h3>${U.date(month,{month:'long',year:'numeric'})}</h3><button data-month-step="1" aria-label="Mes siguiente">${U.icon('arrow')}</button></div><div class="weekdays">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>'<span>'+x+'</span>').join('')}</div><div class="calendar-grid">${cells.join('')}</div><div class="calendar-key"><span><i></i> Hay actividad</span><span>Solo sábados preparados</span></div></section>`:''}<section class="calendar-agenda">${mode==='week'?weekAgenda(selected):`<div class="sectionHead"><h2>${fmtDate(selected)}</h2>${(isAdmin()||isPastor())&&S.events.some(e=>e.start_date<=selected&&e.end_date>=selected)?'<button class="btn primary" data-calendar-add>'+U.icon('plus')+' Actividad</button>':''}</div>${dateAgenda(selected)}`}</section></div>`;}

function weekAgenda(date){const d=new Date(date+'T12:00:00Z'),first=U.addDays(date,-((d.getUTCDay()+6)%7));return `<div class="week-controls"><button class="btn" data-week-step="-7">${U.icon('back')} Anterior</button><span>${fmtShort(first)} — ${fmtShort(U.addDays(first,6))}</span><button class="btn" data-week-step="7">Siguiente ${U.icon('arrow')}</button></div><div class="week-agenda">${Array.from({length:7},(_,i)=>{const key=U.addDays(first,i);return `<div class="week-day"><h3><button data-cal-date="${key}" class="plain-date">${fmtDate(key)}</button></h3>${dateAgenda(key)}</div>`;}).join('')}</div>`;}

function dateAgenda(date){const events=S.events.filter(e=>e.start_date<=date&&e.end_date>=date&&e.status!=='cancelled'),dayIds=new Set(S.days.filter(d=>d.date===date).map(d=>d.id)),items=S.items.filter(i=>dayIds.has(i.day_id)).sort((a,b)=>(a.starts_at||'99').localeCompare(b.starts_at||'99'));return `${events.map(e=>`<div class="agenda-event"><button data-event-open="${e.id}"><b>${esc(e.name)}</b><small>${esc(e.location||'TNT')}</small></button>${canManageEvent(e.id)?`<button class="btn small" data-add-on-date="${date}" data-event-id="${e.id}" aria-label="Agregar actividad a ${esc(e.name)}">${U.icon('plus')}</button>`:''}</div>`).join('')}<div class="agenda-list">${items.map(i=>scheduleItemRow(eventBy(dayBy(i.day_id).event_id),i)).join('')||(!events.length?empty('Sin actividades para este día',''): '<p class="tiny">El evento todavía no tiene horarios cargados.</p>')}</div>`;}

function viewBrief(){const tasks=personalTasks();return `<div class="sectionHead"><h2>Mi resumen de servicio</h2><button class="btn" data-print>${U.icon('download')} Guardar PDF</button></div><div class="briefing-list">${tasks.map(t=>`<article class="card"><h3>${esc(t.title)}</h3><p>${esc(eventBy(t.event_id)?.name||'TNT')} · ${esc(t.planned_start||t.due_at?U.date(t.planned_start||t.due_at,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}):fmtDate(eventBy(t.event_id)?.start_date))}</p><p>${esc(t.description||'')}</p>${t.materials?'<p><b>Materiales:</b> '+esc(t.materials)+'</p>':''}${avatars(taskPeople(t.id))}<div class="chips">${assignChip(myAssignment(t).assignment_status)}</div></article>`).join('')||empty('Sin responsabilidades pendientes','')}${personalItems().map(i=>scheduleItemRow(eventBy(dayBy(i.day_id).event_id),i)).join('')}</div>`;}

function viewFiles(){return `<div class="sectionHead"><h2>Archivos y recursos</h2>${isAdmin()||isPastor()?'<button class="btn primary" data-add-resource>'+U.icon('plus')+' Recurso</button>':''}</div><div class="grid g2">${S.files.filter(f=>!f.module||f.module==='organizacion').map(f=>`<a class="resource-card" href="${esc(U.safeUrl(f.url))}" target="_blank" rel="noopener noreferrer">${U.icon('file')}<div><h3>${esc(f.title)}</h3><p>${esc(f.folder||'General')}</p></div>${U.icon('up')}</a>`).join('')||empty('Todavía no hay recursos compartidos','Agregá documentos, videos o enlaces para tu equipo.')}</div>`;}


function bindNew(){
 $$('[data-open-chat]').forEach(b=>b.onclick=()=>location.href='/chat/');$$('[data-print]').forEach(b=>b.onclick=()=>window.print());$$('[data-reload]').forEach(b=>b.onclick=async()=>{await loadAll();render();});$$('[data-filter]').forEach(b=>b.onclick=()=>{S.activityFilter=b.dataset.filter;render();});$('#activity-event')?.addEventListener('change',e=>{S.activityEvent=e.target.value;render();});$$('[data-past]').forEach(b=>b.onclick=()=>{S.showPast=!S.showPast;render();});$$('[data-new-task]').forEach(b=>b.onclick=chooseTaskEvent);
 $$('[data-cal-date]').forEach(b=>b.onclick=()=>{S.calendarDate=b.dataset.calDate;S.calendarMonth=S.calendarDate.slice(0,7)+'-01';if(S.calendarMode==='week')S.calendarMode='day';render();if(S.calendarDate>=today()&&(isAdmin()||isPastor())&&!S.events.some(e=>e.status!=='cancelled'&&e.start_date<=S.calendarDate&&e.end_date>=S.calendarDate)){const saturday=new Date(S.calendarDate+'T12:00:00Z').getUTCDay()===6;const o=U.modal(fmtDate(S.calendarDate),`<p>No hay ninguna actividad creada en esta fecha.</p><div class="actions">${saturday?'<button class="tnt-button primary" id="create-saturday-on-date">Preparar sábado</button>':''}<button class="tnt-button" id="create-event-on-date">Crear evento</button></div>`);o.querySelector('#create-saturday-on-date')?.addEventListener('click',async()=>{U.closeModal(o);await createSaturday(S.calendarDate);});o.querySelector('#create-event-on-date').onclick=()=>{U.closeModal(o);eventCreateModal()}}});$$('[data-cal-mode]').forEach(b=>b.onclick=()=>{S.calendarMode=b.dataset.calMode;render();});$$('[data-cal-today]').forEach(b=>b.onclick=()=>{S.calendarDate=today();S.calendarMonth=today().slice(0,7)+'-01';render();});$$('[data-month-step]').forEach(b=>b.onclick=async()=>{const d=new Date((S.calendarMonth||today().slice(0,7)+'-01')+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.monthStep));S.calendarMonth=d.toISOString().slice(0,10);S.calendarDate=S.calendarMonth;render();});$$('[data-week-step]').forEach(b=>b.onclick=()=>{S.calendarDate=U.addDays(S.calendarDate||today(),Number(b.dataset.weekStep));render();});$$('[data-calendar-add]').forEach(b=>b.onclick=calendarAdd);$$('[data-add-on-date]').forEach(b=>b.onclick=()=>addCalendarActivity(b.dataset.eventId,b.dataset.addOnDate));$$('[data-item-open]').forEach(b=>b.onclick=()=>scheduleItemDetailModal(b.dataset.itemOpen));$$('[data-add-resource]').forEach(b=>b.onclick=addResource);
}

function chooseTaskEvent(){const events=S.events.filter(e=>canManageEvent(e.id));const o=U.modal('¿Para qué evento?',`<div class="tnt-form"><label for="new-task-event">Evento</label><select id="new-task-event">${events.map(e=>`<option value="${e.id}">${esc(e.name)} · ${fmtShort(e.start_date)}</option>`).join('')}</select><button class="tnt-button primary" id="continue-task">Continuar</button></div>`);o.querySelector('#continue-task').onclick=()=>{const id=o.querySelector('select').value;U.closeModal(o);if(id)taskEditModal(null,id);};}

function calendarAdd(){const date=S.calendarDate||today(),events=S.events.filter(e=>e.start_date<=date&&e.end_date>=date&&e.status!=='cancelled'&&canManageEvent(e.id));if(events.length===1)return addCalendarActivity(events[0].id,date);const o=U.modal('Agregar actividad',`<div class="tnt-form">${events.length?`<label for="cal-event">Evento</label><select id="cal-event">${events.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><button class="tnt-button primary" id="cal-choose">Agregar a este evento</button>`:'<p>Primero creá el evento de este día.</p>'}<button class="tnt-button" id="cal-new">Crear evento</button></div>`);o.querySelector('#cal-choose')?.addEventListener('click',()=>{const id=o.querySelector('select').value;U.closeModal(o);addCalendarActivity(id,date);});o.querySelector('#cal-new').onclick=()=>{U.closeModal(o);eventCreateModal();const f=$('#eventForm');if(f){f.elements.start.value=date;f.elements.end.value=date;}};}

async function addCalendarActivity(eventId,date){S.selectedEvent=eventId;let day=S.days.find(d=>d.event_id===eventId&&d.date===date);if(!day){const r=await sb.from('tnt_schedule_days').insert({event_id:eventId,date,label:fmtDate(date),sort_order:eventDays(eventId).length}).select().single();if(r.error)return U.toast(r.error.message,true);day=r.data;S.days.push(day);}S.selectedDay=day.id;scheduleItemModal();}


async function openActivityChat(taskId,eventId){try{const r=await sb.rpc('tnt_open_activity_chat',{p_task:null,p_event:eventId||taskBy(taskId)?.event_id||null});if(r.error)throw r.error;location.href='/chat/?thread='+encodeURIComponent(r.data);}catch(e){U.toast(e.message||'No pudimos abrir el chat.',true);}}

function addResource(){const o=U.modal('Compartir recurso','<form class="tnt-form"><div><label for="resource-title">Nombre</label><input id="resource-title" name="title" required></div><div><label for="resource-url">Enlace</label><input id="resource-url" name="url" type="url" required placeholder="https://"></div><button class="tnt-button primary" type="submit">Guardar recurso</button><div role="alert"></div></form>');o.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),url=U.safeUrl(f.get('url'));if(!url)return;const r=await sb.from('tnt_library_items').insert({title:String(f.get('title')).trim(),url,folder:'Organización',module:'organizacion',uploaded_by:currentPersonId()}).select().single();if(r.error)return o.querySelector('[role=alert]').textContent=r.error.message;U.closeModal(o);await loadAll();render();};}

async function taskDetailModal(id){let t=taskBy(id),e=eventBy(t?.event_id);if(!t||!e)return;let manager=canManageEvent(e.id),editor=canEditActivity(e.id),mine=myAssignment(t);let [linksR,checkR,commentsR,filesR,privateR]=await Promise.all([sb.from('tnt_task_links').select('*').eq('task_id',id).order('sort_order'),sb.from('tnt_task_checklist').select('*').eq('task_id',id).order('sort_order'),sb.from('tnt_task_comments').select('*').eq('task_id',id).order('created_at'),sb.from('tnt_task_files').select('*').eq('task_id',id).order('created_at'),manager?sb.from('tnt_task_private_notes').select('*').eq('task_id',id).order('created_at'):Promise.resolve({data:[]})]);let links=linksR.data||[],checks=checkR.data||[],comments=commentsR.data||[],files=filesR.data||[],priv=privateR.data||[],assign=S.assignees.filter(a=>a.task_id===id);modal(`${sheetHead(t.title,e.name)}<div class="chips">${statusChip(t.status)}${t.task_type!=='simple'?`<span class="chip priority ${esc(t.priority)}">Prioridad ${esc(PRIORITY_LABEL[t.priority]||t.priority)}</span>`:''}${t.due_at?`<span class="chip">Vence ${new Date(t.due_at).toLocaleString('es-AR')}</span>`:''}</div><div class="grid g2" style="margin-top:13px"><div class="card"><h3>Responsables</h3>${assign.length?`<div class="responsibles">${assign.map(a=>`<button class="personLink" data-person-open="${a.person_id}">${avatarHtml(a.person_id)} ${esc(displayName(a.person_id))} · ${esc(ASSIGN_LABEL[a.assignment_status])}</button>`).join('')}</div>`:'<p>Sin responsables</p>'}</div>${t.task_type!=='simple'?`<div class="card"><h3>Planificación</h3><p>${esc(t.description||'Sin descripción')}</p>${t.materials?`<p><b>Materiales:</b> ${esc(t.materials)}</p>`:''}${t.budget_estimated?`<p><b>Presupuesto:</b> $${Number(t.budget_estimated).toLocaleString('es-AR')}</p>`:''}</div>`:''}</div><p class="tiny task-timing">${t.planned_start?'Horario: '+U.time(t.planned_start):'Horario sin definir'}${t.duration_minutes?' · '+t.duration_minutes+' min':''}</p>${mine?`<div class="card assignment-card" style="margin-top:12px"><h3>Tu participación</h3><p>${esc(ASSIGN_LABEL[mine.assignment_status])}${mine.response_note?' · '+esc(mine.response_note):''}</p>${!['accepted','declined'].includes(mine.assignment_status)?'<div class="actions" style="margin-top:10px"><button class="btn good" data-response="accepted">Confirmar</button><button class="btn danger" data-response="declined">No puedo hacerlo</button></div>':mine.assignment_status==='accepted'?'<div class="actions" style="margin-top:10px"><button class="btn danger" data-response="declined">Ya no puedo hacerlo</button></div>':''}</div>`:''}${manager||mine?.assignment_status==='accepted'?`<div class="card task-review-flow"><h3>Estado de la actividad</h3><p>${t.status==='ready'||t.status==='review'?'Ya está lista para el encuentro.':t.status==='completed'?'Actividad terminada.':t.status==='progress'?'Está en preparación.':'Indicá el avance con dos estados simples.'}</p><div class="actions">${!U.completed(t)&&t.status!=='progress'&&t.status!=='ready'&&t.status!=='review'?'<button class="btn" data-task-status="progress">En curso</button>':''}${!U.completed(t)&&t.status!=='ready'&&t.status!=='review'?'<button class="btn good" data-task-status="ready">Marcar lista</button>':''}${manager&&(t.status==='ready'||t.status==='review')?'<button class="btn" data-task-status="progress">Volver a en curso</button><button class="btn good" data-task-status="completed">Cerrar actividad</button>':''}</div></div>`:''}${t.task_type!=='simple'?`<div class="sectionHead"><h2>Checklist</h2>${manager||mine?'<button class="btn small" id="addCheck">+ Punto</button>':''}</div>${checks.length?`<div class="checkList">${checks.map(c=>`<label class="checkRow"><input type="checkbox" data-check-id="${c.id}" ${c.done?'checked':''}><span style="${c.done?'text-decoration:line-through;color:var(--muted)':''}">${esc(c.text)}</span>${c.assigned_person_id?`<small>${esc(displayName(c.assigned_person_id))}</small>`:''}</label>`).join('')}</div>`:empty('Sin checklist','')}<div class="sectionHead"><h2>Referencias</h2>${manager||mine?'<button class="btn small" id="addLink">+ Link</button>':''}</div><div class="grid">${links.map(linkCard).join('')||empty('Sin links','')}</div><div class="sectionHead"><h2>Archivos</h2>${manager||mine?'<label class="btn small">+ Archivo<input id="taskFile" type="file" hidden></label>':''}</div><div class="actions">${files.map(f=>`<button class="fileBtn" data-open-file="${f.id}" data-file-path="${esc(f.storage_path)}">📎 ${esc(f.file_name)}</button>`).join('')||'<span class="tiny">Sin archivos</span>'}</div><div class="sectionHead"><h2>Indicaciones y consultas</h2></div>${comments.map(c=>`<div class="comment"><b>${esc(displayName(c.person_id))} · ${c.kind==='note'?'Indicación':c.resolved_at?'Consulta resuelta':'Consulta pendiente'}</b><div class="tnt-rich">${TNTEditor.render(c.body,c.body_rich)}</div>${c.kind==='question'&&manager?`<button class="btn small" data-resolve-comment="${c.id}" data-resolved="${!!c.resolved_at}">${c.resolved_at?'Reabrir consulta':'Marcar resuelta'}</button>`:''}</div>`).join('')||'<div class="tiny">No hay consultas pendientes.</div>'}<form class="form" id="commentForm" style="margin-top:10px">${manager?'<div class="field"><label>Tipo de mensaje</label><select name="kind"><option value="note">Indicación para el equipo</option><option value="question">Consulta pendiente</option></select></div>':'<input type="hidden" name="kind" value="question">'}<div class="field"><textarea name="body" placeholder="${manager?'Dejá una indicación o respondé una consulta…':'¿Qué necesitás consultar a los responsables?'}"></textarea></div><button class="btn">Publicar</button></form>${manager?`<div class="sectionHead"><h2>Notas privadas de organizadores</h2><button class="btn small" id="addPrivate">+ Nota privada</button></div>${priv.map(n=>`<div class="comment privateNote"><b>${esc(displayName(n.author_person_id))}</b><p>${esc(n.body)}</p></div>`).join('')||'<div class="tiny">Sin notas privadas</div>'}`:''}<div class="sectionHead"><h2>Subtareas</h2>${manager?'<button class="btn small" id="addSubtask">+ Subtarea</button>':''}</div>${childrenOf(id).length?`<div class="list">${childrenOf(id).map(x=>taskRow(x,myAssignment(x))).join('')}</div>`:'<div class="tiny">Sin subtareas</div>'}`:''}${editor||manager?`<div class="actions" style="margin-top:16px">${editor?'<button class="btn" id="editTask">Editar actividad</button>':''}${manager?'<button class="btn danger" id="deleteTask">Eliminar</button>':''}</div>`:''}`,true);
  $$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));$$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));$$('[data-response]').forEach(b=>b.onclick=()=>assignmentResponse(id,b.dataset.response));$$('[data-task-status]').forEach(b=>b.onclick=()=>setTaskStatus(id,b.dataset.taskStatus));$$('[data-check-id]').forEach(c=>c.onchange=()=>toggleCheck(c.dataset.checkId,c.checked));$$('[data-open-file]').forEach(b=>b.onclick=()=>openTaskFile(b.dataset.filePath));
  const commentEditor=$('#commentForm')?TNTEditor.attach($('#commentForm textarea')):null;$$('[data-resolve-comment]').forEach(b=>b.onclick=async()=>{const r=await sb.from('tnt_task_comments').update({resolved_at:b.dataset.resolved==='true'?null:new Date().toISOString(),resolved_by:b.dataset.resolved==='true'?null:currentPersonId()}).eq('id',b.dataset.resolveComment).select().single();if(r.error)return toast(errMsg(r.error));taskDetailModal(id);});if($('#commentForm'))$('#commentForm').onsubmit=async ev=>{ev.preventDefault();const btn=ev.target.querySelector('button:not([type=button])'),content=commentEditor.get(),body=content.text.trim();if(!body)return;btn.disabled=true;let {error}=await sb.from('tnt_task_comments').insert({task_id:id,person_id:currentPersonId(),body,body_rich:content.html,kind:new FormData(ev.target).get('kind')||'question'});btn.disabled=false;if(error)return toast(errMsg(error));taskDetailModal(id)};
  $('#addCheck')?.addEventListener('click',()=>addChecklistModal(id,checks.length));$('#addLink')?.addEventListener('click',()=>addLinkModal(id,links.length));$('#taskFile')?.addEventListener('change',e2=>uploadTaskFile(id,e2.target.files?.[0]));$('#addPrivate')?.addEventListener('click',()=>addPrivateNoteModal(id));$('#addSubtask')?.addEventListener('click',()=>taskEditModal(null,e.id,id));$('#editTask')?.addEventListener('click',()=>taskEditModal(t,e.id));$('#deleteTask')?.addEventListener('click',async()=>{if(!await U.confirm('¿Eliminar esta tarea, sus subtareas y las actividades vinculadas del cronograma?'))return;let {error}=await sb.rpc('tnt_delete_activity',{p_task:id});if(error)return toast(errMsg(error));closeModal();await loadAll();render()})
}
async function assignmentResponse(id,status){let note=null;if(status==='declined')note=await U.prompt('Si querés, contá brevemente por qué no podés:')||null;let {error}=await sb.rpc('tnt_set_assignment_response',{p_task:id,p_status:status,p_note:note});if(error)return toast(errMsg(error));await loadAll();taskDetailModal(id)}
async function setTaskStatus(id,status){let {error}=await sb.rpc('tnt_set_task_status',{p_task:id,p_status:status});if(error)return toast(errMsg(error));await loadAll();taskDetailModal(id);toast(status==='ready'?'Actividad marcada como lista':status==='progress'?'Actividad en curso':'Actividad terminada')}
async function toggleCheck(id,done){let {error}=await sb.from('tnt_task_checklist').update({done}).eq('id',id);if(error)toast(errMsg(error))}
const originalTaskDetail=taskDetailModal;taskDetailModal=async function(id){await originalTaskDetail(id);const host=$('#modal .sheet');if(!host)return;const b=document.createElement('button');b.className='btn primary context-chat';b.innerHTML=U.icon('chat')+' Chat del evento';b.onclick=()=>openActivityChat(id,null);if(myAssignment(taskBy(id))||canManageEvent(taskBy(id).event_id))host.querySelector('.sheetHead').after(b);if(canManageEvent(taskBy(id).event_id)){const r=document.createElement('button');r.className='btn';r.textContent='Buscar reemplazo';r.onclick=()=>replacementCandidates(id);host.querySelector('.sheetHead').after(r);}};
const originalEventDetail=eventDetailModal;eventDetailModal=function(id){originalEventDetail(id);const host=$('#modal .sheet');if(!host)return;const actions=document.createElement('div');actions.className='event-context';const e=eventBy(id),hasActivities=eventTasks(id).length>0||eventDays(id).some(d=>dayItems(d.id).length>0);actions.innerHTML=`<button class="event-action primary" data-event-schedule>${U.icon('calendar')}<span><b>Ver cronograma</b><small>${hasActivities?'Horarios y actividades':'Todavía vacío'}</small></span></button><button class="event-action" data-event-chat>${U.icon('chat')}<span><b>Chat ${e.kind==='saturday'?'del sábado':'del evento'}</b><small>Se crea automáticamente si hace falta</small></span></button>`;host.querySelector('.sheetHead').after(actions);actions.querySelector('[data-event-schedule]').onclick=()=>{if(!hasActivities){modal(`${sheetHead('Todavía no hay actividades',e.name)}<div class="event-empty"><div class="event-empty-icon">＋</div><h3>Primero cargá una actividad</h3><p>Cuando agregues horarios van a aparecer automáticamente en el cronograma.</p>${canManageEvent(id)?'<button class="btn primary" id="empty-add-activity">Agregar actividad</button>':''}<button class="btn" id="empty-back-event">Volver al sábado</button></div>`);$('#empty-add-activity')?.addEventListener('click',()=>taskEditModal(null,id));$('#empty-back-event')?.addEventListener('click',()=>eventDetailModal(id));return;}clearOrgModal();S.selectedEvent=id;S.selectedDay=eventDays(id)[0]?.id;S.cronTab='schedule';history.replaceState({...history.state,tntOrgView:'schedule',tntOrgOverlay:null},'');S.view='schedule';render();};actions.querySelector('[data-event-chat]').onclick=()=>openActivityChat(null,id);const c=S.checkins.find(x=>x.event_id===id&&x.person_id===currentPersonId()&&!x.checked_out_at);const options=[...((e.start_date<=today()&&e.end_date>=today())?[[c?'Registrar salida':'Ya llegué',()=>checkin(id)]]:[]),...(canManageEvent(id)?[[e.kind==='saturday'?'Editar sábado':'Editar evento',()=>editEvent(id)]]:[]),...((isAdmin()||isPastor())&&e.kind!=='saturday'?[['Duplicar',()=>duplicateEvent(id)]]:[])];if(options.length){const row=document.createElement('div');row.className='actions event-secondary-actions';options.forEach(([label,fn])=>{const b=document.createElement('button');b.className='btn';b.textContent=label;b.onclick=fn;row.append(b);});actions.after(row);}};
async function checkin(eid){const c=S.checkins.find(x=>x.event_id===eid&&x.person_id===currentPersonId()&&!x.checked_out_at);const r=c?await sb.from('tnt_checkins').update({checked_out_at:new Date().toISOString()}).eq('id',c.id).select().single():await sb.from('tnt_checkins').upsert({event_id:eid,person_id:currentPersonId(),checked_in_at:new Date().toISOString(),checked_out_at:null},{onConflict:'event_id,person_id'}).select().single();if(r.error)return U.toast(r.error.message,true);await loadAll();render();eventDetailModal(eid);U.toast(c?'Salida registrada':'¡Ya estás presente!');}
function duplicateEvent(id){const e=eventBy(id),o=U.modal('Duplicar evento',`<form class="tnt-form"><div><label for="copy-name">Nombre</label><input id="copy-name" name="name" value="${esc(e.name+' · copia')}" required></div><div><label for="copy-date">Nueva fecha de inicio</label><input id="copy-date" name="date" type="date" value="${e.start_date}" required></div><label class="switch-row"><input name="team" type="checkbox">Copiar también participantes y responsables</label><p>Se copian tareas, subtareas, checklist, enlaces y cronograma. Los estados vuelven a pendiente.</p><button class="tnt-button primary" type="submit">Crear copia</button><p role="alert"></p></form>`);o.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),b=ev.target.querySelector('[type=submit]');b.disabled=true;const r=await sb.rpc('tnt_copy_event',{p_event:id,p_name:f.get('name'),p_date:f.get('date'),p_team:f.get('team')==='on'});if(r.error){b.disabled=false;return o.querySelector('[role=alert]').textContent=r.error.message;}U.closeModal(o);await loadAll();render();eventDetailModal(r.data);};}
function editEvent(id){const e=eventBy(id),o=U.modal(e.kind==='saturday'?'Editar sábado':'Editar evento',`<form class="tnt-form"><div><label for="ev-name">Nombre</label><input id="ev-name" name="name" value="${esc(e.name)}" required></div><div><label for="ev-description">Descripción</label><textarea id="ev-description" name="description">${esc(e.description||'')}</textarea></div><div><label for="ev-location">Lugar</label><input id="ev-location" name="location" value="${esc(e.location||'')}"></div><div class="tnt-form-grid"><div><label for="ev-start">Desde</label><input id="ev-start" type="date" name="start" value="${e.start_date}" ${e.kind==='saturday'?'disabled':''} required></div><div><label for="ev-end">Hasta</label><input id="ev-end" type="date" name="end" value="${e.end_date}" ${e.kind==='saturday'?'disabled':''} required></div></div><div><label for="ev-status">Estado</label><select id="ev-status" name="status">${[['planning','En preparación'],['confirmed','Confirmado'],['live','En curso'],['completed','Terminado'],['cancelled','Cancelado']].map(([v,l])=>`<option value="${v}" ${e.status===v?'selected':''}>${l}</option>`).join('')}</select></div><p>${e.kind==='saturday'?'El sábado conserva sus tareas al cambiar el nombre o estado. Para otra fecha, prepará un sábado nuevo.':'Para trasladar todo el cronograma a otra fecha, usá Duplicar evento. Acá podés ajustar el intervalo manteniendo los días ya planificados dentro de él.'}</p><button class="tnt-button primary" type="submit">Guardar cambios</button><p role="alert"></p></form>`);o.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),start=e.kind==='saturday'?e.start_date:f.get('start'),end=e.kind==='saturday'?e.end_date:f.get('end');if(end<start)return o.querySelector('[role=alert]').textContent='Revisá el intervalo de fechas.';if(eventDays(id).some(d=>d.date&&(d.date<start||d.date>end)))return o.querySelector('[role=alert]').textContent='Hay actividades fuera de ese intervalo. Ampliá las fechas o usá Duplicar evento.';const r=await sb.from('tnt_events').update({name:f.get('name').trim(),description:f.get('description'),location:f.get('location'),start_date:start,end_date:end,status:f.get('status')}).eq('id',id).select().single();if(r.error)return o.querySelector('[role=alert]').textContent=r.error.message;U.closeModal(o);await loadAll();render();eventDetailModal(id);};}
function projectEvent(id){const e=eventBy(id),d=document.createElement('dialog');d.className='org-projection';document.body.append(d);const paint=()=>{d.innerHTML=`<header><div><span class="eyebrow">TNT · MODO PANTALLA</span><h1>${esc(e.name)}</h1><p>${esc(e.location||'')} · ${fmtDate(e.start_date)}</p></div><button class="btn" id="projection-close">Cerrar</button></header>${eventDays(id).map(day=>`<h2>${esc(day.label)} · ${fmtShort(day.date)}</h2><div class="projection-list">${dayItems(day.id).map(i=>`<article class="${i.run_status==='live'?'is-live':''}"><b>${fmtTime(i.starts_at)}</b><div><h3>${esc(i.title)}</h3><p>${itemPeople(i.id).map(pid=>esc(displayName(pid))).join(' · ')||'Sin responsables asignados'}</p></div><span>${RUN_LABEL[i.run_status||'pending']}</span></article>`).join('')}</div>`).join('')||'<p>Todavía no hay actividades.</p>'}`;d.querySelector('#projection-close').onclick=()=>d.close();};paint();d.showModal();const timer=setInterval(async()=>{if(document.hidden)return;const days=eventDays(id).map(x=>x.id);if(!days.length)return;const r=await sb.from('tnt_schedule_items').select('*').in('day_id',days);if(!r.error){S.items=S.items.filter(i=>!days.includes(i.day_id)).concat(r.data||[]);paint();}},10000);d.addEventListener('close',()=>{clearInterval(timer);d.remove();});}
function replacementCandidates(taskId){const target=taskBy(taskId),active=new Set(taskPeople(taskId)),day=target.planned_start?U.dateKey(target.planned_start):eventBy(target.event_id)?.start_date;const overlap=(a,b)=>{if(!a.planned_start||!b.planned_start)return false;const as=Date.parse(a.planned_start),bs=Date.parse(b.planned_start);return as<bs+(b.duration_minutes||60)*60000&&bs<as+(a.duration_minutes||60)*60000;};const rows=staffPeople().filter(p=>!active.has(p.id)).map(p=>{const tasks=S.tasks.filter(t=>taskPeople(t.id).includes(p.id)&&!U.completed(t.status)),av=S.availability.find(a=>a.person_id===p.id&&a.date===day),unavailable=av?.status==='unavailable',conflict=tasks.some(t=>t.id!==taskId&&overlap(t,target));return{p,load:tasks.length,unavailable,conflict,known:!!av,score:(unavailable?1000:0)+(conflict?500:0)+tasks.length};}).sort((a,b)=>a.score-b.score);const o=U.modal('Buscar reemplazo',`<p>Ordenados por disponibilidad registrada y tareas activas. Revisá la propuesta antes de asignar.</p>${rows.slice(0,20).map(x=>`<div class="chat-participant replacement-row">${avatarHtml(x.p.id)}<div><b>${esc(displayName(x.p.id))}</b><small>${x.unavailable?'No disponible':x.conflict?'Coincide con otra tarea':x.load+' tareas activas'}${!x.known?' · Disponibilidad sin confirmar':''}</small></div><button class="btn" data-candidate="${x.p.id}">Asignar</button></div>`).join('')||'<p>No hay más personas disponibles en el equipo.</p>'}`);o.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=async()=>{const x=rows.find(x=>x.p.id===b.dataset.candidate);if((x.unavailable||x.conflict)&&!await U.confirm('Hay una dificultad de disponibilidad. ¿Querés asignar igual?'))return;const r=await sb.rpc('tnt_save_task',{p_id:taskId,p_event:target.event_id,p_values:target,p_people:[...taskPeople(taskId),x.p.id]});if(r.error)return U.toast(r.error.message,true);U.closeModal(o);await loadAll();render();taskDetailModal(taskId);});}
const originalItemDetail=scheduleItemDetailModal;scheduleItemDetailModal=function(id){originalItemDetail(id);const i=S.items.find(x=>x.id===id),d=dayBy(i?.day_id),host=$('#modal .sheet');if(!host||!d)return;if(i.task_id&&(taskPeople(i.task_id).includes(currentPersonId())||canManageEvent(d.event_id))){const cb=document.createElement('button');cb.className='btn context-chat';cb.innerHTML=U.icon('chat')+' Chat del evento';cb.onclick=()=>openActivityChat(i.task_id,null);host.querySelector('.sheetHead').after(cb);}S.selectedDay=d.id;S.selectedEvent=d.event_id;if(canManageEvent(d.event_id)){const row=document.createElement('div');row.className='actions live-controls';for(const [status,label] of Object.entries(RUN_LABEL)){const b=document.createElement('button');b.className='btn '+(i.run_status===status?'primary':'');b.textContent=label;b.onclick=async()=>{const r=await sb.from('tnt_schedule_items').update({run_status:status}).eq('id',id).select().single();if(r.error)return U.toast(r.error.message,true);await loadAll();render();scheduleItemDetailModal(id);};row.append(b);}host.querySelector('.sheetHead').after(row);}};
